try:
    from shadowself_plus.tasks import TaskRegistry
except ImportError:
    # fallback: اگر پکیج کنار فایل نبود، نسخهٔ سادهٔ داخلی همان رفتار را دارد
    class TaskRegistry:
        def __init__(self, loop=None):
            self._loop = loop
            self._tasks = {}

        def spawn(self, name, coro):
            if self._loop is not None:
                task = self._loop.create_task(coro, name=name)
            else:
                task = asyncio.create_task(coro, name=name)
            self._tasks[name] = task
            return task

        def is_alive(self, name):
            task = self._tasks.get(name)
            return bool(task) and not task.done()

        def restart(self, name, coro):
            if self.is_alive(name):
                return self._tasks[name]
            return self.spawn(name, coro)

        def alive_names(self):
            return [n for n, t in self._tasks.items() if not t.done()]

