import re
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

TEHRAN = TEHRAN_TZ

FA_DIGITS = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
EN_DIGITS = str.maketrans("0123456789", "۰۱۲۳۴۵۶۷۸۹")
WEEKDAYS = ["دوشنبه", "سه‌شنبه", "چهارشنبه", "پنجشنبه", "جمعه", "شنبه", "یکشنبه"]

CAPTCHA_TTL_SECONDS = 300  # ۵ دقیقه فرصت برای دکمه


def fa_number(value) -> str:
    """تبدیل عدد/رشته به ارقام فارسی."""
    return str(value).translate(EN_DIGITS)


# --------------------------------------------------------------------------
# سکوت شبانه
# --------------------------------------------------------------------------

def is_quiet_now(now: datetime | None = None, start_hour: int = 23, end_hour: int = 7) -> bool:
    """آیا الان در بازه سکوت شبانه است؟ پشتیبانی از بازه‌های شبانه (شروع > پایان)."""
    now = now or datetime.now(TEHRAN)
    hour = now.hour
    if start_hour == end_hour:
        return False
    if start_hour < end_hour:
        return start_hour <= hour < end_hour
    return hour >= start_hour or hour < end_hour


def quiet_window_text(start_hour: int, end_hour: int) -> str:
    return f"{fa_number(f'{start_hour:02d}')}:۰۰ تا {fa_number(f'{end_hour:02d}')}:۰۰"


# --------------------------------------------------------------------------
# نمایش تاریخ شمسی
# --------------------------------------------------------------------------

def persian_datetime_text(dt: datetime, now: datetime | None = None) -> str:
    """تاریخ شمسی + برچسب نسبی: «امروز ۱۴:۳۰» / «فردا ۰۹:۰۰» / «۱۴۰۵/۰۵/۲۶ - ۱۴:۳۰»."""
    dt = dt.astimezone(TEHRAN)
    now = (now or datetime.now(TEHRAN)).astimezone(TEHRAN)
    delta = (dt.date() - now.date()).days
    time_str = dt.strftime("%H:%M")
    if delta == 0:
        return f"امروز {time_str}"
    if delta == 1:
        return f"فردا {time_str}"
    if delta == 2:
        return f"پس‌فردا {time_str}"
    try:
        import jdatetime
        jd = jdatetime.date.fromgregorian(date=dt.date())
        return f"{fa_number(f'{jd.year:04d}')}/{fa_number(f'{jd.month:02d}')}/{fa_number(f'{jd.day:02d}')} - {time_str}"
    except Exception:
        return f"{WEEKDAYS[dt.weekday()]} {time_str}"


def jalali_today_text(now: datetime | None = None) -> str:
    """تاریخ امروز شمسی + روز هفته + میلادی."""
    now = now or datetime.now(TEHRAN)
    try:
        import jdatetime
        jd = jdatetime.date.fromgregorian(date=now.date())
        weekday = WEEKDAYS[now.weekday()]
        return f"📅 {weekday} {fa_number(f'{jd.year:04d}')}/{fa_number(f'{jd.month:02d}')}/{fa_number(f'{jd.day:02d}')} — {now.strftime('%Y/%m/%d')}"
    except Exception:
        return f"📅 {WEEKDAYS[now.weekday()]} {now.strftime('%Y/%m/%d')}"


# --------------------------------------------------------------------------
# پارسر زمان‌بندی طبیعی
# --------------------------------------------------------------------------

# «فردا ساعت ۹ به علی پیام بده سلام» / «ساعت ۱۴:۳۰ به امیر بگو بیا»
_SCHEDULE_RE = re.compile(
    r"^(?P<when>.+?)\s+به\s+(?:کاربری\s+که\s+اسمش|کاربر\s+به\s+نام)?\s*"
    r"(?P<target>.+?)\s+(?:هست\s+)?(?:بگو|پیام\s*بده)\s+(?P<message>.+)$",
    re.DOTALL,
)


def parse_schedule_request(text: str) -> dict | None:
    """«فردا ساعت ۹ به علی پیام بده سلام» → {'when','target','message','when_text'}.

    برمی‌گرداند None اگر ساختار «به ... پیام بده ...» را نداشته باشد.
    """
    text = str(text or "").strip()
    m = _SCHEDULE_RE.match(text)
    if not m:
        return None
    when_phrase = re.sub(r"\s+", " ", m.group("when").translate(FA_DIGITS)).strip()
    target = re.sub(r"\s+هست$", "", m.group("target").strip()).strip()
    message = m.group("message").strip()
    if not when_phrase or not target or not message:
        return None
    # «ساعت 9» تنها → «امروز ساعت 9»
    if re.fullmatch(r"ساعت\s*\d{1,2}(?::\d{2})?", when_phrase):
        when_phrase = "امروز " + when_phrase
    return {"when_phrase": when_phrase, "target": target, "message": message}


# --------------------------------------------------------------------------
# خلاصه روزانه گروه
# --------------------------------------------------------------------------

def build_group_summary(stats: dict, group_name: str = "گروه") -> str:
    """خلاصه فعالیت روزانه از آمار گروه."""
    stats = stats or {}
    messages = int(stats.get("messages", 0) or 0)
    media = int(stats.get("media", 0) or 0)
    links = int(stats.get("links", 0) or 0)
    deleted = int(stats.get("deleted", 0) or 0)
    spam = int(stats.get("spam", 0) or 0)
    users = stats.get("users", {}) or {}
    top = sorted(users.items(), key=lambda kv: int(kv[1] or 0), reverse=True)[:5]
    top_lines = "\n".join(f"• کاربر {uid}: {count} پیام" for uid, count in top) or "—"
    return (
        f"📊 خلاصه روزانه «{group_name}»\n\n"
        f"✉️ پیام‌ها: {messages}\n"
        f"🖼 مدیا: {media} | 🔗 لینک: {links}\n"
        f"🗑 حذف‌شده: {deleted} | 🚫 اسپم: {spam}\n\n"
        f"👥 کاربران فعال:\n{top_lines}"
    )


# --------------------------------------------------------------------------
# کپچای ورود
# --------------------------------------------------------------------------

def captcha_is_expired(created_ts: float, now_ts: float | None = None, ttl: float = CAPTCHA_TTL_SECONDS) -> bool:
    now_ts = now_ts if now_ts is not None else __import__("time").time()
    return (now_ts - float(created_ts or 0)) > ttl


# --------------------------------------------------------------------------
# واچ‌لیست / آرشیو خودکار — تطبیق کلمات کلیدی
# --------------------------------------------------------------------------

def parse_keyword_list(text: str) -> list[str]:
    """«علی، بلیط، پروژه» → ['علی', 'بلیط', 'پروژه'] — حذف فاصله‌های اضافه و علائم."""
    import re as _re
    parts = _re.split(r"[،,;؛|]", str(text or ""))
    out = []
    for part in parts:
        word = _re.sub(r"\s+", " ", part).strip()
        if word and word not in out:
            out.append(word[:60])
    return out


def text_has_any_keyword(text: str, keywords: list[str]) -> str | None:
    """اولین کلیدواژه‌ای که در متن هست را برمی‌گرداند؛ وگرنه None."""
    text = str(text or "")
    lowered = text.casefold()
    for kw in keywords or []:
        if not kw:
            continue
        if kw.casefold() in lowered:
            return kw
    return None


# --------------------------------------------------------------------------
# پست متقاطع هوشمند
# --------------------------------------------------------------------------

_CROSSPOST_RE = re.compile(r"پست متقاطع\s+(.+?)\s+به\s+(.+)$", re.DOTALL)


def parse_crosspost_request(text: str) -> dict | None:
    """«پست متقاطع کانال خبر به کانال پشتیبان» → {'source','dest'}."""
    text = str(text or "").strip()
    m = _CROSSPOST_RE.match(text)
    if not m:
        return None
    source = m.group(1).strip()
    dest = m.group(2).strip()
    if not source or not dest:
        return None
    return {"source": source, "dest": dest}


# --------------------------------------------------------------------------
# گزارش مالی با نمودار ASCII
# --------------------------------------------------------------------------

def build_expense_report(expenses: list, budget: float | None = None,
                         month_prefix: str | None = None, bar_width: int = 20) -> str:
    """گزارش مالی: مجموع، دسته‌بندی، نمودار میله‌ای، بودجه.

    expenses: لیست dictهای {"amount", "category", "created_at"(ISO)}
    month_prefix: «2026-08» — فقط هزینه‌های آن ماه؛ None = همه.
    """
    expenses = expenses or []
    rows = []
    for item in expenses:
        try:
            amount = float(item.get("amount", 0) or 0)
        except (TypeError, ValueError):
            continue
        created = str(item.get("created_at", "") or "")
        if month_prefix and not created.startswith(month_prefix):
            continue
        rows.append({
            "amount": amount,
            "category": str(item.get("category", "سایر") or "سایر")[:30],
        })

    total = sum(r["amount"] for r in rows)
    by_category: dict[str, float] = {}
    for r in rows:
        by_category[r["category"]] = by_category.get(r["category"], 0.0) + r["amount"]

    top = sorted(by_category.items(), key=lambda kv: kv[1], reverse=True)[:6]
    max_val = top[0][1] if top else 1.0

    lines = [f"💰 **گزارش مالی**" + (f" ({month_prefix})" if month_prefix else " (همه)")]
    lines.append(f"📌 مجموع: **{total:,.0f}** | تعداد: {len(rows)}")
    if budget is not None:
        remaining = budget - total
        lines.append(f"🎯 بودجه: {budget:,.0f} | باقی‌مانده: {remaining:,.0f} {'✅' if remaining >= 0 else '⚠️'}")
    if not top:
        lines.append("\n📭 هزینه‌ای ثبت نشده.")
        return "\n".join(lines)

    lines.append("\n📊 **دسته‌ها:**")
    for category, value in top:
        width = max(1, int(bar_width * value / max_val))
        lines.append(f"{category:<20} {value:>12,.0f}  {'█' * width}")
    return "\n".join(lines)


# --------------------------------------------------------------------------
# گیت تأیید فرمان‌های حساس (v8) — الگوها عیناً از هندلرهای کد گرفته شده‌اند
# --------------------------------------------------------------------------

_SENSITIVE_PATTERNS = (
    re.compile(r"پاک\s+کردن\s+تاریخچه\s+.+"),          # پاک کردن تاریخچه X
    re.compile(r"حذف\s+چت\s+.+"),                        # حذف چت X
    re.compile(r"بلاک کن\s+.+"),                         # بلاک کن X (نه «بلاک لیست»)
    re.compile(r"(?:از\s+.+?\s+لفت\s+بده|(?:لفت\s+از|ترک\s+کن|ترک\s+کانال|ترک\s+گروه)\s+.+)"),
)

CONFIRM_PREFIX = "تأیید"


def is_sensitive_command(text: str) -> bool:
    """آیا این فرمان از نوع حساس است (حذف/پاک‌کردن/لفت/بلاک)؟"""
    text = str(text or "").strip()
    if not text:
        return False
    return any(p.fullmatch(text) for p in _SENSITIVE_PATTERNS)


def confirm_sensitive(text: str) -> str | None:
    """«تأیید حذف چت X» → «حذف چت X»؛ اگر تأیید بود ولی حساس نبود → 'NOT_SENSITIVE'.

    خروجی:
    - str   : فرمان تأییدشده (برای اجرا)
    - 'NOT_SENSITIVE': پیشوند تأیید بود ولی فرمان حساس نیست
    - None  : این پیام تأیید نیست
    """
    text = str(text or "").strip()
    if not text.startswith(CONFIRM_PREFIX + " "):
        return None
    inner = text[len(CONFIRM_PREFIX):].strip()
    if not inner:
        return None
    if is_sensitive_command(inner):
        return inner
    return "NOT_SENSITIVE"


# --------------------------------------------------------------------------
# بکاپ خودکار (v8)
# --------------------------------------------------------------------------

def next_backup_time(last_backup_ts: float, interval_seconds: int = 24 * 3600,
                     now_ts: float | None = None) -> float:
    """زمان بکاپ بعدی؛ اگر هنوز بکاپی نرفته، همین الان (برای شروع فوری)."""
    now_ts = now_ts if now_ts is not None else __import__("time").time()
    if not last_backup_ts:
        return now_ts
    return last_backup_ts + max(3600, int(interval_seconds))


def format_backup_caption(now_ts: float | None = None) -> str:
    """کپشن فایل بکاپ — زمان به وقت تهران."""
    from datetime import datetime as _dt
    from zoneinfo import ZoneInfo as _ZI
    now_ts = now_ts if now_ts is not None else __import__("time").time()
    dt = _dt.fromtimestamp(now_ts, tz=_ZI("Asia/Tehran"))
    return f"🔐 بکاپ خودکار سلف — {dt.strftime('%Y-%m-%d %H:%M')}"


