def get_help(topic: str) -> str | None:
    """راهنمای یک موضوع؛ با تطبیق فازی ساده (شامل بودن)."""
    topic = str(topic or "").strip().casefold()
    if not topic:
        return None
    for key, guide in HELP_GUIDE.items():
        if key.casefold() == topic or key.casefold() in topic:
            return guide
    return None


import json
import logging
import time
import urllib.error
import urllib.request

logger = logging.getLogger("shadowself.ai")


class CircuitBreaker:
    """سه حالت: closed → open (بعد از threshold خطا) → half-open (probe) → closed."""

    CLOSED, OPEN, HALF_OPEN = "closed", "open", "half_open"

    def __init__(self, name: str, fail_threshold: int = 3, cooldown_seconds: float = 120.0):
        self.name = name
        self.fail_threshold = max(1, int(fail_threshold))
        self.cooldown = max(0.1, float(cooldown_seconds))
        self.state = self.CLOSED
        self._failures = 0
        self._opened_at = 0.0

    def allow(self) -> bool:
        if self.state == self.CLOSED:
            return True
        if self.state == self.OPEN:
            if time.monotonic() - self._opened_at >= self.cooldown:
                self.state = self.HALF_OPEN  # یک درخواست آزمایشی
                return True
            return False
        return True  # half_open: فقط یک بار — با اولین شکست دوباره باز می‌شود

    def record_success(self) -> None:
        self._failures = 0
        self.state = self.CLOSED

    def record_failure(self) -> None:
        self._failures += 1
        if self.state == self.HALF_OPEN or self._failures >= self.fail_threshold:
            self.state = self.OPEN
            self._opened_at = time.monotonic()
            logger.warning("circuit breaker «%s» باز شد (%d شکست)", self.name, self._failures)

    @property
    def failures(self) -> int:
        return self._failures


class AIProvider:
    """یک ارائه‌دهنده‌ی سازگار با OpenAI Chat Completions."""

    def __init__(self, name: str, base_url: str, api_key: str, model: str, priority: int = 100):
        self.name = name
        self.base_url = str(base_url).rstrip("/")
        self.api_key = api_key
        self.model = model
        self.priority = int(priority)

    def build_payload(self, messages, system_prompt=None, temperature=0.1, max_tokens=1200):
        full_messages = []
        if system_prompt:
            full_messages.append({"role": "system", "content": str(system_prompt)[:4000]})
        full_messages.extend(list(messages)[-40:])  # سقف پیام‌ها
        return json.dumps({
            "model": self.model,
            "messages": full_messages,
            "temperature": max(0.0, min(float(temperature), 1.5)),
            "max_tokens": max(64, min(int(max_tokens), 4000)),
        }, ensure_ascii=False).encode("utf-8")


class AIProviderManager:
    """مدیر چند ارائه‌دهنده با failover و circuit breaker."""

    def __init__(self, providers=None, timeout: float = 60.0, fail_threshold: int = 3, cooldown: float = 120.0):
        self.providers: list[AIProvider] = []
        self.timeout = timeout
        self.fail_threshold = fail_threshold
        self.cooldown = cooldown
        self._breakers: dict[str, CircuitBreaker] = {}
        # آمار مصرف — برای فرمان «مصرف هوش مصنوعی»
        self.stats = {
            "calls": 0, "successes": 0, "errors": 0, "failovers": 0,
            "total_tokens": 0, "last_latency_ms": 0.0, "latency_sum": 0.0,
        }
        if providers:
            for p in providers:
                self.add_provider(p)

    def add_provider(self, provider: AIProvider) -> None:
        self.providers.append(provider)
        self.providers.sort(key=lambda p: p.priority)  # عدد کوچک‌تر = اولویت بالاتر
        if provider.name not in self._breakers:
            self._breakers[provider.name] = CircuitBreaker(provider.name, self.fail_threshold, self.cooldown)

    def _ordered(self) -> list[AIProvider]:
        """ارائه‌دهنده‌های مجاز (breaker بسته) به ترتیب اولویت."""
        return [p for p in self.providers if self._breakers[p.name].allow()]

    def _call_sync(self, provider: AIProvider, payload: bytes) -> str:
        request = urllib.request.Request(
            f"{provider.base_url}/chat/completions",
            data=payload,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {provider.api_key}",
                "User-Agent": "ShadowSalfPlus/1.0",
            },
            method="POST",
        )
        with urllib.request.urlopen(request, timeout=self.timeout) as response:
            return response.read().decode("utf-8")

    def _parse_content(self, body: str) -> tuple[str | None, str | None]:
        try:
            data = json.loads(body)
            content = data.get("choices", [{}])[0].get("message", {}).get("content")
            if isinstance(content, str) and content.strip():
                usage = data.get("usage") or {}
                self.stats["total_tokens"] += int(usage.get("total_tokens", 0) or 0)
                return content, None
            return None, "پاسخ مدل قابل خواندن نبود."
        except (json.JSONDecodeError, IndexError, KeyError, TypeError):
            return None, "پاسخ سرویس JSON معتبر نبود."

    async def chat(self, messages, system_prompt=None, temperature=0.1, max_tokens=1200, loop=None):
        """فراخوانی با failover؛ (محتوا, خطا) برمی‌گرداند."""
        import asyncio

        if not self.providers:
            return None, "هیچ ارائه‌دهنده‌ای تنظیم نشده است."
        self.stats["calls"] += 1
        last_error = "همهٔ ارائه‌دهنده‌ها در دسترس نبودند."
        started = time.monotonic()

        for provider in self._ordered():
            payload = provider.build_payload(messages, system_prompt, temperature, max_tokens)
            try:
                if loop is not None:
                    body = await loop.run_in_executor(None, self._call_sync, provider, payload)
                else:
                    import asyncio as _a
                    body = await _a.to_thread(self._call_sync, provider, payload)
                content, error = self._parse_content(body)
                if error is None:
                    self._breakers[provider.name].record_success()
                    self.stats["successes"] += 1
                    self.stats["last_latency_ms"] = (time.monotonic() - started) * 1000
                    self.stats["latency_sum"] += self.stats["last_latency_ms"]
                    return content, None
                last_error = error
            except urllib.error.HTTPError as exc:
                last_error = self._http_error_text(exc, provider)
                self._breakers[provider.name].record_failure()
            except (urllib.error.URLError, TimeoutError, ConnectionError) as exc:
                last_error = f"ارتباط با «{provider.name}» برقرار نشد: {getattr(exc, 'reason', exc)}"
                self._breakers[provider.name].record_failure()
            except Exception as exc:  # noqa: BLE001 — failover باید همه‌چیز را بگیرد
                last_error = f"خطای «{provider.name}»: {exc}"
                self._breakers[provider.name].record_failure()
            self.stats["errors"] += 1
            # اگر ارائه‌دهنده‌ی دیگری مانده، failover ثبت می‌شود
            if any(self._breakers[p.name].allow() for p in self.providers if p is not provider):
                self.stats["failovers"] += 1
                logger.warning("failover به ارائه‌دهنده‌ی بعدی: %s", last_error)

        self.stats["last_latency_ms"] = (time.monotonic() - started) * 1000
        return None, last_error

    @staticmethod
    def _http_error_text(exc: urllib.error.HTTPError, provider: AIProvider) -> str:
        code = exc.code
        try:
            detail = json.loads(exc.read().decode("utf-8", errors="replace")[:500])
            detail = str(detail.get("error", {}).get("message", "")).strip()
        except Exception:
            detail = ""
        if code == 429:
            return f"خطای ۴۲۹ (سهمیه/نرخ) در «{provider.name}»"
        if code in (401, 403):
            return f"کلید «{provider.name}» نامعتبر/بدون دسترسی است."
        if code == 404:
            return f"مدل «{provider.model}» در «{provider.name}» پیدا نشد."
        if code >= 500:
            return f"خطای موقت سرور ({code}) در «{provider.name}»"
        return detail or f"خطای {code} از «{provider.name}»"

    def summary(self) -> str:
        """گزارش خلاصه برای فرمان «مصرف هوش مصنوعی»."""
        lines = [
            f"📊 درخواست‌ها: {self.stats['calls']} (موفق {self.stats['successes']} / خطا {self.stats['errors']})",
            f"🔁 Failoverها: {self.stats['failovers']}",
            f"🔤 توکن مصرفی: {self.stats['total_tokens']:,}",
        ]
        for p in self.providers:
            br = self._breakers[p.name]
            lines.append(f"• {p.name} ({p.model}): {br.state} | شکست‌ها: {br.failures}")
        return "\n".join(lines)


import re
import time


def estimate_tokens(text: str) -> int:
    """تخمین ساده: فارسی/عمومی ≈ ۴ کاراکتر به ازای هر توکن."""
    return max(1, len(str(text or "")) // 4)


# الگوهای ساده برای استخراج حقایق بلندمدت از پیام‌های عادی
FACT_PATTERNS = [
    (r"اسم(?:م)?\s+(?:من\s+)?(?:هست)?\s*([آ-یa-zA-Z]+)", "name"),
    (r"من\s+([آ-یa-zA-Z]+)\s+هستم", "name"),
    (r"([۰-۹0-9]{1,2})\s*سالمه", "age"),
    (r"سنم\s+([۰-۹0-9]{1,2})", "age"),
    (r"اهل\s+([آ-ی\s]{2,20}?)(?:\s+هستم)?$", "city"),
    (r"شماره(?:م)?\s*(?:هست)?\s*((?:\+?98|0)?9\d{9})", "phone"),
    (r"([آ-یa-zA-Z]{2,20})\s+کار(?: میکنم|می‌کنم)", "job"),
]


class ChatMemory:
    """تاریخچه‌ی چت با بودجه توکن + خلاصه‌سازی + حقایق."""

    def __init__(self, max_tokens: int = 4000, max_messages: int = 200):
        self.max_tokens = int(max_tokens)
        self.max_messages = int(max_messages)
        self.history: list[dict] = []        # {"role","text","ts"}
        self.summary: str = ""               # خلاصه‌ی پیام‌های قدیمی
        self.facts: dict[str, str] = {}      # کلید → مقدار بلندمدت
        self.summarize_hook = None           # callable(summary_old, messages) → new_summary

    # ------------------------------------------------------------------ ثبت
    def add(self, role: str, text: str, ts: float | None = None) -> None:
        text = str(text or "").strip()
        if not text:
            return
        self.history.append({"role": role, "text": text[:2000], "ts": ts or time.time()})
        self.trim_to_budget()

    def add_user(self, text: str) -> None:
        self.add("user", text)
        self._extract_facts(text)

    # ------------------------------------------------------------------ بودجه
    def used_tokens(self) -> int:
        return estimate_tokens(self.summary) + sum(estimate_tokens(m["text"]) for m in self.history)

    def trim_to_budget(self) -> None:
        """پیام‌های قدیمی را به بودجه‌ی توکن برمی‌گرداند؛ اضافه‌ها به خلاصه می‌روند."""
        if len(self.history) > self.max_messages:
            self._rollup(self.history[: len(self.history) - self.max_messages])
            self.history = self.history[-self.max_messages:]
        while self.used_tokens() > self.max_tokens and len(self.history) > 8:
            # نصف قدیمی‌ترین‌ها را rollup کن (نه همه را یکجا)
            drop = max(2, len(self.history) // 2)
            self._rollup(self.history[:drop])
            self.history = self.history[drop:]

    def _rollup(self, messages: list[dict]) -> None:
        if not messages:
            return
        if self.summarize_hook is not None:
            try:
                self.summary = str(self.summarize_hook(self.summary, messages))[:2000]
                return
            except Exception:
                pass
        # fallback: بدون هوش مصنوعی، فقط اولین/آخرین را نگه دار
        first, last = messages[0], messages[-1]
        self.summary = (self.summary + " | " if self.summary else "") + \
            f"{first['role']}:{first['text'][:120]} … {last['role']}:{last['text'][:120]}"
        self.summary = self.summary[-2000:]

    # ------------------------------------------------------------------ حقایق
    def _extract_facts(self, text: str) -> None:
        fa_digits = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
        normalized = text.translate(fa_digits)
        for pattern, key in FACT_PATTERNS:
            m = re.search(pattern, normalized)
            if m:
                value = m.group(1).strip()
                if len(value) >= 2 and (key != "name" or value not in ("هستم", "من", "اسم")):
                    self.facts[key] = value

    def remember(self, key: str, value: str) -> None:
        value = str(value or "").strip()
        if value:
            self.facts[key] = value[:500]

    def get_fact(self, key: str) -> str | None:
        return self.facts.get(key)

    # ------------------------------------------------------------------ خروجی
    def context_messages(self, system_prefix: str | None = None, max_tokens: int | None = None) -> list[dict]:
        """پیام‌های آماده برای Chat Completions: سیستم + خلاصه + حقایق + تاریخچه."""
        budget = max_tokens or self.max_tokens
        system_parts = []
        if system_prefix:
            system_parts.append(system_prefix)
        if self.facts:
            system_parts.append(
                "حقایق شناخته‌شده درباره کاربر: " +
                "، ".join(f"{k}={v}" for k, v in self.facts.items())
            )
        if self.summary:
            system_parts.append("خلاصه گفت‌وگوهای قبلی: " + self.summary)
        messages = []
        if system_parts:
            messages.append({"role": "system", "content": " | ".join(system_parts)[:3000]})

        used = estimate_tokens(" ".join(p["content"] for p in messages))
        tail = []
        for item in reversed(self.history):
            tok = estimate_tokens(item["text"])
            if used + tok > budget:
                break
            tail.append(item)
            used += tok
        messages.extend(reversed(tail))
        return messages

    # ------------------------------------------------------------------ ذخیره
    def to_dict(self) -> dict:
        return {
            "history": self.history[-self.max_messages:],
            "summary": self.summary,
            "facts": self.facts,
        }

    @classmethod
    def from_dict(cls, data: dict, **kwargs) -> "ChatMemory":
        mem = cls(**kwargs)
        mem.history = list(data.get("history", []))[-mem.max_messages:]
        mem.summary = str(data.get("summary", ""))
        mem.facts = {str(k): str(v) for k, v in data.get("facts", {}).items()}
        return mem

    def __len__(self) -> int:
        return len(self.history)


import re
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

TEHRAN = TEHRAN_TZ

FA_DIGITS = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")

NUMBER_WORDS = {
    "یک": 1, "یه": 1, "یکی": 1,
    "دو": 2, "سه": 3, "چهار": 4, "پنج": 5, "شش": 6, "شیش": 6,
    "هفت": 7, "هشت": 8, "نه": 9, "ده": 10,
    "یازده": 11, "دوازده": 12, "سی": 30, "چهل": 40, "پنجاه": 50,
    "شصت": 60, "هفتاد": 70, "هشتاد": 80, "نود": 90, "صد": 100,
}

DURATION_UNITS = {
    "ثانیه": 1, "دقیقه": 60, "ساعت": 3600, "روز": 86400, "هفته": 604800,
}

WEEKDAYS = ["دوشنبه", "سه‌شنبه", "چهارشنبه", "پنجشنبه", "جمعه", "شنبه", "یکشنبه"]
# ایندکس weekday پایتون: 0=دوشنبه … 6=یکشنبه (هم‌راستا با WEEKDAYS بالا)

DAY_PART_OFFSET = {"صبح": 9, "ظهر": 12, "عصر": 16, "شب": 21, "بعدازظهر": 16, "بعد از ظهر": 16}

DURATION_RE = re.compile(
    r"(?P<num>\d+|یک|یه|یکی|دو|سه|چهار|پنج|شش|شیش|هفت|هشت|نه|ده|یازده|دوازده)"
    r"\s*(?P<unit>ثانیه|دقیقه|ساعت|روز|هفته)"
    r"\s*(?P<rel>بعد|دیگه|دیگر|بعدش)?"
)

CLOCK_RE = re.compile(
    r"(?:ساعت\s*)?(?P<h>\d{1,2})(?::(?P<m>\d{2}))?\s*(?P<part>صبح|ظهر|عصر|شب|بعدازظهر|بعد از ظهر)?"
)

RELATIVE_DAYS = {
    "امروز": 0, "امشب": 0, "فردا": 1, "فرداش": 1,
    "پس فردا": 2, "پس‌فردا": 2, "دیروز": -1, "پریروز": -2,
}


def _num(value: str) -> int:
    v = value.strip().translate(FA_DIGITS)
    if v.isdigit():
        return int(v)
    return NUMBER_WORDS.get(v, 1)


class PersianTimeParser:
    """پارسر مرکزی زمان فارسی — همه ماژول‌ها فقط از این استفاده کنند."""

    @staticmethod
    def parse_duration(text: str, default: int | None = None) -> int | None:
        """«۲ ساعت بعد» / «بعد از 5 دقیقه» → ثانیه. برمی‌گرداند None اگر نامعتبر."""
        normalized = str(text or "").translate(FA_DIGITS)
        m = DURATION_RE.search(normalized)
        if m:
            amount = _num(m.group("num"))
            seconds = amount * DURATION_UNITS[m.group("unit")]
            return max(5, min(seconds, 30 * 86400))
        if "فردا" in normalized:
            return 86400
        return default

    @staticmethod
    def parse_clock(text: str, now: datetime | None = None) -> datetime | None:
        """«ساعت ۱۴:۳۰» یا «ساعت 3 بعدازظهر» → ساعتِ بعدیِ تهران (aware)."""
        now = (now or datetime.now(TEHRAN)).astimezone(TEHRAN)
        normalized = re.sub(r"\s+", " ", str(text or "").translate(FA_DIGITS))

        # فقط اگر «ساعت» داشته باشد یا فرمت HH:MM باشد → وگرنه عدد عادی است
        has_word = "ساعت" in normalized
        m = CLOCK_RE.search(normalized)
        if not m:
            return None
        if not has_word and m.group("m") is None:
            return None
        hour = _num(m.group("h"))
        minute = _num(m.group("m") or "0")
        if hour > 23 or minute > 59:
            return None
        if m.group("part"):
            part = m.group("part").replace(" ", "")
            if part == "ظهر":
                hour = 12
            elif part in ("بعدازظهر", "عصر", "شب"):
                # «ساعت 3 بعدازظهر» = ۱۵:۰۰ ، «ساعت 9 شب» = ۲۱:۰۰
                if hour <= 6:
                    hour += 12
            # «صبح» ساعت را تغییر نمی‌دهد (۱ تا ۱۲)
        target = now.replace(hour=hour, minute=minute, second=0, microsecond=0)
        if target <= now:
            target += timedelta(days=1)
        return target

    @staticmethod
    def parse_datetime(text: str, now: datetime | None = None) -> tuple[datetime | None, str]:
        """ترکیب کامل: «فردا ساعت ۹ صبح» / «دوشنبه ساعت ۱۴» / «۲ ساعت بعد»."""
        now = (now or datetime.now(TEHRAN)).astimezone(TEHRAN)
        normalized = re.sub(r"\s+", " ", str(text or "").translate(FA_DIGITS))

        # مدت نسبی: «۲ ساعت بعد» / «بعد از 5 دقیقه» → مستقیم برمی‌گردد
        m = DURATION_RE.search(normalized)
        if m:
            amount = _num(m.group("num"))
            seconds = amount * DURATION_UNITS[m.group("unit")]
            seconds = max(5, min(seconds, 30 * 86400))
            return now + timedelta(seconds=seconds), "مدت نسبی"

        # روز نسبی/مطلق
        day_delta = 0
        for word, delta in RELATIVE_DAYS.items():
            if word in normalized:
                day_delta = delta
                break
        else:
            for idx, weekday in enumerate(WEEKDAYS):
                if weekday in normalized:
                    day_delta = (idx - now.weekday()) % 7
                    if day_delta == 0:
                        day_delta = 7 if "بعد" in normalized else 0
                    break

        clock = PersianTimeParser.parse_clock(normalized, now)
        if clock is not None:
            base = (now + timedelta(days=day_delta)) if day_delta else now
            target = base.replace(hour=clock.hour, minute=clock.minute, second=0, microsecond=0)
            if day_delta == 0 and target <= now:
                target += timedelta(days=1)
            return target, "ساعت مشخص"

        if day_delta:
            base = (now + timedelta(days=day_delta)).replace(hour=9, minute=0, second=0, microsecond=0)
            return base, "روز مشخص"

        return None, "تشخیص داده نشد"

    @staticmethod
    def format_tehran(dt: datetime) -> str:
        """نمایش دوستانه: «امروز ۱۴:۳۰» / «فردا ۹:۰۰» / «دوشنبه ۱۴:۰۰»."""
        dt = dt.astimezone(TEHRAN)
        today = datetime.now(TEHRAN).date()
        delta = (dt.date() - today).days
        day = {0: "امروز", 1: "فردا", 2: "پس فردا"}.get(delta, WEEKDAYS[dt.weekday()])
        return f"{day} {dt.strftime('%H:%M')}"


import asyncio
import logging
from typing import Any, Coroutine

logger = logging.getLogger("shadowself.tasks")


class TaskRegistry:
    """reference همه‌ی taskهای بلندمدت را نگه می‌دارد و مرگ غیرمنتظره را لاگ می‌کند."""

    def __init__(self, loop: asyncio.AbstractEventLoop | None = None):
        self._loop = loop
        self._tasks: dict[str, asyncio.Task] = {}

    def spawn(self, name: str, coro: Coroutine) -> asyncio.Task:
        """ساخت task با نگه‌داشتن reference؛ مرگ غیرمنتظره لاگ می‌شود (task می‌ماند).

        از loop صریح استفاده می‌کند تا خارج از حلقه‌ی در حال اجرا هم کار کند
        (مثل _start_background_tasks در ربات که با client.loop صدا زده می‌شود).
        """
        if self._loop is None:
            task = asyncio.create_task(coro, name=name)
        else:
            task = self._loop.create_task(coro, name=name)
        self._tasks[name] = task

        def _on_done(t: asyncio.Task) -> None:
            if t.cancelled():
                return
            exc = t.exception()
            if exc is not None:
                logger.error("task «%s» به‌صورت غیرمنتظره مرد: %r", name, exc)
            # reference نگه داشته می‌شود تا GC task را جمع نکند؛
            # اگر زنده بماند، watchdog می‌تواند ری‌استارتش کند.

        task.add_done_callback(_on_done)
        return task

    def is_alive(self, name: str) -> bool:
        task = self._tasks.get(name)
        return bool(task) and not task.done()

    def restart(self, name: str, coro: Coroutine) -> asyncio.Task | None:
        """اگر task مرده بود، دوباره می‌سازد؛ در غیر این صورت همان را برمی‌گرداند."""
        if self.is_alive(name):
            return self._tasks[name]
        return self.spawn(name, coro)

    def alive_names(self) -> list[str]:
        return [name for name, task in self._tasks.items() if not task.done()]

    def dead_names(self) -> list[str]:
        return [name for name, task in self._tasks.items() if task.done() and not task.cancelled()]

    def report(self) -> dict[str, str]:
        return {
            name: ("running" if not task.done() else "done")
            for name, task in self._tasks.items()
        }

    def cancel_all(self) -> None:
        for task in list(self._tasks.values()):
            task.cancel()

    def __len__(self) -> int:
        return len(self._tasks)

