def _load_local_env():
    """فایل .env کنار برنامه/مسیر اجرا را بدون وابستگی اضافه بارگذاری می‌کند."""
    allowed = {
        "TELEGRAM_API_ID", "TELEGRAM_API_HASH", "TELEGRAM_OWNER_ID",
        "TELEGRAM_SESSION_STRING", "SHADOWSELF_DATA_DIR", "SHADOWSELF_AUTO_TAKEOVER",
        "SHADOWSELF_LOCK_DIR", "TELEGRAM_SESSION_DIR", "TELEGRAM_DOWNLOAD_DIR", "NARA_API_KEY", "NARA_MODEL",
        "NARA_VISION_MODEL", "NARA_BASE_URL", "OPENAI_API_KEY", "OPENAI_BASE_URL",
    }
    candidates = [Path.cwd() / ".env", Path(__file__).resolve().parent / ".env"]
    seen = set()
    for env_path in candidates:
        try:
            resolved = env_path.resolve()
            if resolved in seen or not resolved.is_file():
                continue
            seen.add(resolved)
            for raw_line in resolved.read_text(encoding="utf-8").splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                if key not in allowed:
                    continue
                value = value.strip()
                if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
                    value = value[1:-1]
                os.environ.setdefault(key, value)
        except Exception as exc:
            logger.warning("خواندن فایل محیطی %s انجام نشد: %s", env_path, exc)


_load_local_env()

