    @classmethod
    def _is_allowed_ai_run_command(cls, command):
        normalized = re.sub(r"\s+", " ", str(command or "").strip())
        if not normalized or len(normalized) > 2000:
            return False
        if any(ord(char) < 32 and char not in "\n\t" for char in normalized):
            return False
        forbidden_safety_bypass = (
            "بازکردن قفل تبچی", "باز کردن قفل تبچی", "تبچی عادی بازکردن قفل",
            "تبچی vip بازکردن قفل", "خاموش کردن محافظ", "محافظ ریسک خاموش",
            "لغو توقف ایمنی", "دور زدن توقف ایمنی",
        )
        lowered = normalized.casefold()
        if any(phrase in lowered for phrase in forbidden_safety_bypass):
            return False
        if "تبچی" in lowered and "خاموش" in lowered and any(
            marker in lowered for marker in ("محافظ", "ریسک", "توقف ایمنی")
        ):
            return False
        return any(
            re.fullmatch(pattern, normalized, flags=re.DOTALL)
            for pattern in cls.AI_RUN_COMMAND_PATTERNS
        )

