# ============================================================================
# Mixin با ۱۰۰ متد
# ============================================================================

class ExtensionsMixin:
    """۱۰۰ قابلیت جدید برای ShadowSelf — Mixin ایمن، بدون خراب کردن چیزی."""

    # ---------- State Initialization ----------
    def _init_extension_state(self):
        """اگه state اکستنشن‌ها وجود نداره، می‌سازه. امن برای فراخوانی چندباره."""
        if not hasattr(self, "_extension_state_initialized"):
            for key in EXTENSION_STATE_KEYS:
                if not hasattr(self, key):
                    if key in ("pomodoro_sessions", "focus_sessions", "goals",
                              "water_log", "sleep_log", "journal_morning",
                              "journal_night", "gratitude_log", "negative_thoughts",
                              "exercise_log", "step_log", "calorie_log",
                              "lottery_history", "group_rules",
                              "ai_post_channels", "ai_post_drafts",
                              "ai_post_history", "ai_post_stats_log"):
                        setattr(self, key, [])
                    elif key in ("custom_welcome", "custom_goodbye"):
                        setattr(self, key, "")
                    elif key in ("antiflood_config",):
                        setattr(self, key, {"enabled": False, "max_per_minute": 5})
                    elif key in ("rate_limit_config",):
                        setattr(self, key, {"enabled": False, "max_messages": 5})
                    elif key in ("ai_post_config",):
                        # پیکربندی AI پست
                        setattr(self, key, {
                            "enabled": False,           # روشن/خاموش
                            "topic": "",                # موضوع اصلی
                            "tone": "صمیمی",            # لحن
                            "length": "متوسط",          # کوتاه/متوسط/بلند
                            "include_hashtags": True,   # هشتگ
                            "include_emoji": True,      # ایموجی
                            "search_query": "",         # کوئری جستجو
                            "schedule_hours": 0,        # فاصله زمانی (ساعت)
                            "last_published": 0,        # آخرین انتشار
                            # === فیلدهای جدید ===
                            "target_chat_id": None,     # مقصد انتشار (None = همین چت)
                            "target_chat_title": "",    # نام مقصد (نمایشی)
                            "batch_size": 1,            # تعداد پست در هر سری
                            "batch_interval_min": 60,   # فاصله بین پست‌ها (دقیقه)
                            "batch_active": False,      # آیا سری فعاله
                            "batch_total_sent": 0,      # تعداد پست‌های ارسال‌شده در سری فعلی
                            "batch_target_total": 0,    # هدف کل سری
                        })
            # state های تک‌متغیره
            if not hasattr(self, "pomodoro_active"):
                self.pomodoro_active = None
            if not hasattr(self, "focus_active"):
                self.focus_active = None
            self._extension_state_initialized = True

    # ---------- Producer: بهره‌وری ----------
    async def cmd_pomodoro_start(self, event, text):
        """شروع جلسهٔ پومودورو."""
        self._init_extension_state()
        self.pomodoro_active = {
            "started_at": time.time(),
            "duration": 25 * 60,  # ۲۵ دقیقه پیش‌فرض
            "chat_id": str(event.chat_id),
        }
        await event.message.edit(
            "🍅 **پومودورو شروع شد!**\n\n"
            "⏱ زمان: ۲۵ دقیقه\n"
            "💡 برای توقف: `پومودورو توقف`\n"
            "📊 برای وضعیت: `پومودورو وضعیت`",
            parse_mode=None,
        )
        return True

    async def cmd_pomodoro_stop(self, event, text):
        if not self.pomodoro_active:
            await event.message.edit("⚠️ پومودورو فعالی نیست.", parse_mode=None)
            return True
        elapsed = int(time.time() - self.pomodoro_active["started_at"])
        mins = elapsed // 60
        self.pomodoro_sessions.append({
            "at": datetime.now().isoformat(timespec="seconds"),
            "duration_minutes": mins,
        })
        self.pomodoro_sessions = self.pomodoro_sessions[-100:]
        self.pomodoro_active = None
        self._save_state()
        await event.message.edit(
            f"⏹ **پومودورو متوقف شد**\n\n"
            f"⏱ زمان سپری‌شده: {mins} دقیقه\n"
            f"📚 کل جلسات: {len(self.pomodoro_sessions)}",
            parse_mode=None,
        )
        return True

    async def cmd_pomodoro_status(self, event, text):
        if not self.pomodoro_active:
            await event.message.edit("⚠️ پومودورو فعالی نیست.", parse_mode=None)
            return True
        elapsed = int(time.time() - self.pomodoro_active["started_at"])
        remaining = max(0, self.pomodoro_active["duration"] - elapsed)
        await event.message.edit(
            f"🍅 **پومودورو فعال**\n\n"
            f"⏱ گذشته: {elapsed // 60} دقیقه\n"
            f"⏳ باقی‌مانده: {remaining // 60} دقیقه و {remaining % 60} ثانیه",
            parse_mode=None,
        )
        return True

    async def cmd_focus_start(self, event, text):
        m = re.match(r"^تمرکز شروع\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        minutes = int(m.group(1))
        if minutes < 1 or minutes > 480:
            await event.message.edit("❌ بازه مجاز: ۱ تا ۴۸۰ دقیقه.", parse_mode=None)
            return True
        self.focus_active = {
            "started_at": time.time(),
            "duration": minutes * 60,
        }
        await event.message.edit(
            f"🎯 **تمرکز شروع شد!**\n\n"
            f"⏱ مدت: {minutes} دقیقه\n"
            f"💡 برای پایان: `تمرکز توقف`",
            parse_mode=None,
        )
        return True

    async def cmd_focus_stop(self, event, text):
        if not self.focus_active:
            await event.message.edit("⚠️ جلسهٔ تمرکز فعالی نیست.", parse_mode=None)
            return True
        elapsed = int(time.time() - self.focus_active["started_at"])
        self.focus_sessions.append({
            "at": datetime.now().isoformat(timespec="seconds"),
            "duration_minutes": elapsed // 60,
        })
        self.focus_sessions = self.focus_sessions[-100:]
        self.focus_active = None
        self._save_state()
        await event.message.edit(
            f"⏹ **تمرکز تمام شد**\n\n"
            f"⏱ مدت: {elapsed // 60} دقیقه\n"
            f"📚 کل جلسات: {len(self.focus_sessions)}",
            parse_mode=None,
        )
        return True

    async def cmd_goal_set(self, event, text):
        m = re.match(r"^هدف جدید\s+(.+)$", text)
        if not m:
            return False
        goal_text = m.group(1).strip()[:200]
        goal_id = len(self.goals) + 1
        self.goals.append({
            "id": goal_id,
            "text": goal_text,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "done": False,
        })
        self._save_state()
        await event.message.edit(
            f"🎯 **هدف #{goal_id} ثبت شد**\n\n"
            f"📌 {goal_text}\n\n"
            f"💡 تکمیل: `هدف انجام {goal_id}`",
            parse_mode=None,
        )
        return True

    async def cmd_goal_list(self, event, text):
        if not self.goals:
            await event.message.edit("📭 هدفی ثبت نشده.\nنمونه: `هدف جدید ۱۰ کیلو وزن کم کنم`", parse_mode=None)
            return True
        active = [g for g in self.goals if not g.get("done")]
        done = [g for g in self.goals if g.get("done")]
        rows = []
        for g in active[:20]:
            rows.append(f"#{g['id']} ⏳ {g['text']}")
        text_out = "🎯 **اهداف فعال:**\n\n" + "\n".join(rows) if rows else "هیچ هدف فعالی نیست."
        if done:
            text_out += f"\n\n✅ **تکمیل‌شده:** {len(done)} مورد"
        await event.message.edit(text_out, parse_mode=None)
        return True

    async def cmd_goal_done(self, event, text):
        m = re.match(r"^هدف انجام\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        goal_id = int(m.group(1))
        for g in self.goals:
            if g.get("id") == goal_id:
                g["done"] = True
                g["done_at"] = datetime.now().isoformat(timespec="seconds")
                self._save_state()
                await event.message.edit(f"🎉 **هدف #{goal_id} تکمیل شد!**\n\n📌 {g['text']}", parse_mode=None)
                return True
        await event.message.edit(f"❌ هدف #{goal_id} پیدا نشد.", parse_mode=None)
        return True

    async def cmd_water_log(self, event, text):
        today = datetime.now().strftime("%Y-%m-%d")
        self.water_log.append({"at": datetime.now().isoformat(timespec="seconds"), "date": today})
        # فقط امروز
        today_count = sum(1 for w in self.water_log if w.get("date") == today)
        await event.message.edit(
            f"💧 **آب ثبت شد!**\n\n"
            f"📊 امروز: {today_count} لیوان\n"
            f"💡 وضعیت: `آب امروز`",
            parse_mode=None,
        )
        self._save_state()
        return True

    async def cmd_water_count(self, event, text):
        today = datetime.now().strftime("%Y-%m-%d")
        today_count = sum(1 for w in self.water_log if w.get("date") == today)
        # میانگین ۷ روز اخیر
        last_7 = []
        for i in range(7):
            d = (datetime.now() - timedelta(days=i)).strftime("%Y-%m-%d")
            c = sum(1 for w in self.water_log if w.get("date") == d)
            last_7.append(c)
        avg = sum(last_7) // 7 if last_7 else 0
        await event.message.edit(
            f"💧 **آب امروز:** {today_count} لیوان\n\n"
            f"📊 میانگین ۷ روز: {avg} لیوان\n"
            f"🎯 هدف: ۸ لیوان در روز",
            parse_mode=None,
        )
        return True

    async def cmd_sleep_log(self, event, text):
        m = re.match(r"^خواب\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)\s*(ساعت|دقیقه)?$", text)
        if not m:
            return False
        value = float(m.group(1))
        unit = m.group(2) or "ساعت"
        hours = value if unit == "ساعت" else value / 60.0
        if hours < 0 or hours > 24:
            await event.message.edit("❌ بازه مجاز: ۰ تا ۲۴ ساعت.", parse_mode=None)
            return True
        self.sleep_log.append({
            "at": datetime.now().isoformat(timespec="seconds"),
            "hours": hours,
        })
        self.sleep_log = self.sleep_log[-100:]
        self._save_state()
        quality = "عالی" if hours >= 7 else "کم" if hours < 6 else "خوب"
        await event.message.edit(
            f"😴 **خواب ثبت شد:** {hours:.1f} ساعت\n\n"
            f"💡 کیفیت: {quality}",
            parse_mode=None,
        )
        return True

    async def cmd_journal_morning(self, event, text):
        m = re.match(r"^صبح یادداشت\s+(.+)$", text)
        if not m:
            return False
        note = m.group(1).strip()[:500]
        today = datetime.now().strftime("%Y-%m-%d")
        self.journal_morning.append({"date": today, "text": note, "at": datetime.now().isoformat(timespec="seconds")})
        self.journal_morning = self.journal_morning[-100:]
        self._save_state()
        await event.message.edit("☀️ **یادداشت صبح ثبت شد**\n\nروز خوبی داشته باشی! 🌅", parse_mode=None)
        return True

    async def cmd_journal_night(self, event, text):
        m = re.match(r"^شب یادداشت\s+(.+)$", text)
        if not m:
            return False
        note = m.group(1).strip()[:500]
        today = datetime.now().strftime("%Y-%m-%d")
        self.journal_night.append({"date": today, "text": note, "at": datetime.now().isoformat(timespec="seconds")})
        self.journal_night = self.journal_night[-100:]
        self._save_state()
        await event.message.edit("🌙 **یادداشت شب ثبت شد**\n\nخواب خوب! 💤", parse_mode=None)
        return True

    async def cmd_gratitude(self, event, text):
        m = re.match(r"^شکرگزاری\s+(.+)$", text)
        if not m:
            return False
        item = m.group(1).strip()[:200]
        today = datetime.now().strftime("%Y-%m-%d")
        self.gratitude_log.append({"date": today, "text": item, "at": datetime.now().isoformat(timespec="seconds")})
        self.gratitude_log = self.gratitude_log[-200:]
        self._save_state()
        await event.message.edit(f"💚 **شکرگزاری ثبت شد**\n\n🙏 {item}", parse_mode=None)
        return True

    async def cmd_negative_thought(self, event, text):
        m = re.match(r"^منفی\s+(.+)$", text)
        if not m:
            return False
        item = m.group(1).strip()[:200]
        today = datetime.now().strftime("%Y-%m-%d")
        self.negative_thoughts.append({"date": today, "text": item, "at": datetime.now().isoformat(timespec="seconds")})
        self.negative_thoughts = self.negative_thoughts[-200:]
        self._save_state()
        # پاسخ حمایتی ساده
        encouragements = [
            "این افکار طبیعی هستن. یه نفس عمیق بکش 🌬",
            "تو از این قوی‌تری. ادامه بده 💪",
            "این فقط یه لحظه‌ست. فردا بهتر میشه 🌅",
            "خودت رو قضاوت نکن. هر روز فرصت تازه‌ست 🌱",
        ]
        msg = random.choice(encouragements)
        await event.message.edit(f"💙 **افکار منفی ثبت شد**\n\n📝 {item}\n\n💡 {msg}", parse_mode=None)
        return True

    async def cmd_exercise_log(self, event, text):
        m = re.match(r"^ورزش\s+(.+)$", text)
        if not m:
            return False
        item = m.group(1).strip()[:200]
        today = datetime.now().strftime("%Y-%m-%d")
        self.exercise_log.append({"date": today, "text": item, "at": datetime.now().isoformat(timespec="seconds")})
        self.exercise_log = self.exercise_log[-200:]
        self._save_state()
        await event.message.edit(f"🏃 **ورزش ثبت شد**\n\n💪 {item}", parse_mode=None)
        return True

    async def cmd_step_count(self, event, text):
        m = re.match(r"^قدم\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        steps = int(m.group(1))
        if steps < 0 or steps > 100000:
            await event.message.edit("❌ بازه مجاز: ۰ تا ۱۰۰٬۰۰۰ قدم.", parse_mode=None)
            return True
        today = datetime.now().strftime("%Y-%m-%d")
        self.step_log.append({"date": today, "steps": steps, "at": datetime.now().isoformat(timespec="seconds")})
        self.step_log = self.step_log[-100:]
        # مجموع امروز
        total_today = sum(s["steps"] for s in self.step_log if s.get("date") == today)
        self._save_state()
        # پیام تشویقی
        msg = "🚶 **قدم‌ها ثبت شد**\n\n"
        msg += f"📊 این نوبت: {steps:,} قدم\n"
        msg += f"📈 امروز: {total_today:,} قدم\n"
        if total_today >= 10000:
            msg += "\n🎉 عالی! به هدف روزانه رسیدی!"
        elif total_today >= 5000:
            msg += "\n💪 نیمه‌راه! ادامه بده"
        await event.message.edit(msg, parse_mode=None)
        return True

    async def cmd_calorie_log(self, event, text):
        m = re.match(r"^کالری\s+([\d۰-۹]+)(?:\s+(.+))?$", text)
        if not m:
            return False
        cal = int(m.group(1))
        food = (m.group(2) or "").strip()[:100]
        if cal < 0 or cal > 20000:
            await event.message.edit("❌ بازه مجاز: ۰ تا ۲۰٬۰۰۰ کالری.", parse_mode=None)
            return True
        today = datetime.now().strftime("%Y-%m-%d")
        self.calorie_log.append({"date": today, "calories": cal, "food": food, "at": datetime.now().isoformat(timespec="seconds")})
        self.calorie_log = self.calorie_log[-200:]
        # مجموع امروز
        total_today = sum(c["calories"] for c in self.calorie_log if c.get("date") == today)
        self._save_state()
        await event.message.edit(
            f"🍽 **کالری ثبت شد**\n\n"
            f"📊 این مورد: {cal} کالری"
            f"{f' ({food})' if food else ''}\n"
            f"📈 امروز: {total_today:,} کالری",
            parse_mode=None,
        )
        return True

    async def cmd_daily_report(self, event, text):
        today = datetime.now().strftime("%Y-%m-%d")
        # جمع‌آوری همه
        water = sum(1 for w in self.water_log if w.get("date") == today)
        steps = sum(s["steps"] for s in self.step_log if s.get("date") == today)
        cals = sum(c["calories"] for c in self.calorie_log if c.get("date") == today)
        sleep_today = [s["hours"] for s in self.sleep_log[-1:]]  # آخرین خواب
        gratitudes = [g for g in self.gratitude_log if g.get("date") == today]
        morning = [j for j in self.journal_morning if j.get("date") == today]
        night = [j for j in self.journal_night if j.get("date") == today]
        exs = [e for e in self.exercise_log if e.get("date") == today]
        goals_done_today = len([g for g in self.goals if g.get("done") and g.get("done_at", "").startswith(today)])

        msg = f"📊 **گزارش روزانه — {today}**\n\n"
        msg += f"💧 آب: {water} لیوان\n"
        msg += f"🚶 قدم: {steps:,}\n"
        msg += f"🍽 کالری: {cals:,}\n"
        if sleep_today:
            msg += f"😴 خواب دیشب: {sleep_today[0]:.1f} ساعت\n"
        if exs:
            msg += f"🏃 ورزش: {len(exs)} مورد\n"
        if gratitudes:
            msg += f"💚 شکرگزاری: {len(gratitudes)} مورد\n"
        if morning:
            msg += f"☀️ یادداشت صبح: دارد\n"
        if night:
            msg += f"🌙 یادداشت شب: دارد\n"
        if goals_done_today:
            msg += f"🎯 اهداف تکمیل‌شده: {goals_done_today}\n"
        await event.message.edit(msg, parse_mode=None)
        return True

