    async def cmd_personality_test(self, event, text):
        traits = [
            ("رهبر", "👑", "شما فردی رهبر و با اعتماد به نفس هستید."),
            ("خلاق", "🎨", "شما ذهنی خلاق و پر از ایده‌های نو دارید."),
            ("حساس", "💝", "شما فردی حساس و مهربان هستید."),
            ("منطقی", "🧠", "شما با منطق و دقت فکر می‌کنید."),
            ("اجتماعی", "🤝", "شما فردی اجتماعی و پر انرژی هستید."),
            ("آرام", "🧘", "شما فردی آرام و متفکر هستید."),
            ("ماجراجو", "🏔", "شما عاشق تجربه‌های تازه هستید."),
        ]
        trait, emoji, desc = random.choice(traits)
        scores = {t[0]: random.randint(40, 95) for t in traits}
        sorted_scores = sorted(scores.items(), key=lambda x: -x[1])
        msg = f"🧠 **تست شخصیت**\n\n"
        msg += f"شما بیشتر: {emoji} **{trait}**\n"
        msg += f"📊 {desc}\n\n"
        msg += "📈 نمره شخصیتی:\n"
        for name, score in sorted_scores[:5]:
            bar = "█" * (score // 10) + "░" * (10 - score // 10)
            msg += f"  {name}: {bar} {score}%\n"
        await event.message.edit(msg, parse_mode=None)
        return True

    async def cmd_love_test(self, event, text):
        m = re.match(r"^تست عشق\s+(\S+)$", text)
        if not m:
            return False
        name = m.group(1)
        compatibility = random.randint(50, 99)
        if compatibility >= 90:
            verdict = "💕 عشق واقعی! یه رابطهٔ عالی در پیشه."
        elif compatibility >= 75:
            verdict = "💛 سازگاری خوب. با کمی تلاش موفق میشید."
        elif compatibility >= 60:
            verdict = "💚 متوسط. نیاز به گفتگو دارید."
        else:
            verdict = "💙 سخت ولی غیرممکن نیست. صبور باشید."
        await event.message.edit(
            f"💕 **تست عشق**\n\n"
            f"👫 {name}\n"
            f"💘 سازگاری: {compatibility}%\n\n"
            f"{verdict}",
            parse_mode=None,
        )
        return True

    async def cmd_compatibility(self, event, text):
        m = re.match(r"^سازگاری\s+(\S+)\s+(\S+)$", text)
        if not m:
            return False
        name1, name2 = m.group(1), m.group(2)
        # بر اساس حرف اول هر نام
        score = (sum(ord(c) for c in name1) + sum(ord(c) for c in name2)) % 50 + 50
        aspects = [
            ("💬 ارتباط", random.randint(60, 99)),
            ("💕 عشق", random.randint(50, 99)),
            ("🤝 اعتماد", random.randint(60, 99)),
            ("🎯 اهداف مشترک", random.randint(50, 95)),
        ]
        msg = f"💞 **سازگاری {name1} و {name2}**\n\n"
        msg += f"📊 امتیاز کلی: {score}%\n\n"
        for asp, val in aspects:
            bar = "█" * (val // 10) + "░" * (10 - val // 10)
            msg += f"  {asp}: {bar} {val}%\n"
        await event.message.edit(msg, parse_mode=None)
        return True

