    # ---------- Producer: ابزار ----------
    async def cmd_qr_generate(self, event, text):
        m = re.match(r"^QR\s+(.+)$", text)
        if not m:
            return False
        content = m.group(1).strip()[:500]
        # الگوریتم ساده: نمایش پیام + لینک به سرویس QR
        try:
            import qrcode
            from PIL import Image as PILImage
            qr = qrcode.QRCode(version=1, box_size=10, border=2)
            qr.add_data(content)
            qr.make(fit=True)
            img = qr.make_image(fill_color="black", back_color="white")
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            await event.client.send_file(
                event.chat_id,
                buf,
                caption=f"🔳 **QR Code ساخته شد**\n\n📝 محتوا: `{content[:100]}`",
                parse_mode=None,
            )
            await event.message.delete()
        except ImportError:
            # اگه qrcode نبود، یه placeholder نشون بده
            await event.message.edit(
                f"🔳 **QR Code**\n\n"
                f"📝 محتوا: `{content}`\n\n"
                f"⚠️ برای ساخت تصویر QR، کتابخانهٔ `qrcode` باید نصب باشه:\n"
                f"`pip install qrcode[pil]`\n\n"
                f"💡 یا از سرویس‌های آنلاین استفاده کن.",
                parse_mode=None,
            )
        return True

