    async def cmd_currency_convert(self, event, text):
        m = re.match(r"^تبدیل\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)\s+(دلار|یورو|پوند|تومان|تتر|بیت‌کوین|اتریوم)\s+(?:به|به\s+)\s*(دلار|یورو|پوند|تومان|تتر|بیت‌کوین|اتریوم)$", text)
        if not m:
            return False
        amount = float(m.group(1))
        from_cur = m.group(2)
        to_cur = m.group(3)
        # نرخ‌های تقریبی (واقعی نیست!)
        rates_to_toman = {
            "تومان": 1,
            "دلار": 700000,
            "یورو": 760000,
            "پوند": 880000,
            "تتر": 700000,
            "بیت‌کوین": 700000 * 60000,
            "اتریوم": 700000 * 3500,
        }
        if from_cur not in rates_to_toman or to_cur not in rates_to_toman:
            await event.message.edit("❌ ارز پشتیبانی نمیشه.", parse_mode=None)
            return True
        toman = amount * rates_to_toman[from_cur]
        result = toman / rates_to_toman[to_cur]
        await event.message.edit(
            f"💱 **تبدیل ارز**\n\n"
            f"💵 {amount:,.2f} {from_cur}\n"
            f"💴 = {result:,.2f} {to_cur}\n\n"
            f"⚠️ نرخ‌ها تقریبی هستن. برای نرخ دقیق از سایت‌های معتبر استفاده کن.",
            parse_mode=None,
        )
        return True

    async def cmd_loan_calc(self, event, text):
        m = re.match(r"^وام\s+([\d۰-۹]+)\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        principal = int(m.group(1))
        rate = float(m.group(2))
        months = int(m.group(3))
        if principal <= 0 or rate <= 0 or months <= 0 or months > 600:
            await event.message.edit("❌ ورودی نامعتبر.", parse_mode=None)
            return True
        monthly_rate = rate / 12 / 100
        if monthly_rate == 0:
            monthly_payment = principal / months
        else:
            monthly_payment = (principal * monthly_rate * (1 + monthly_rate) ** months) / \
                              ((1 + monthly_rate) ** months - 1)
        total = monthly_payment * months
        interest = total - principal
        await event.message.edit(
            f"💰 **ماشین حساب وام**\n\n"
            f"💵 اصل: {principal:,} تومان\n"
            f"📊 نرخ سالانه: {rate}%\n"
            f"📅 مدت: {months} ماه\n\n"
            f"💳 قسط ماهانه: **{monthly_payment:,.0f}** تومان\n"
            f"💸 کل پرداختی: {total:,.0f} تومان\n"
            f"📈 کل سود: {interest:,.0f} تومان",
            parse_mode=None,
        )
        return True

    async def cmd_bmi_calc(self, event, text):
        m = re.match(r"^BMI\s+([\d۰-۹]+)\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)$", text)
        if not m:
            return False
        height_cm = int(m.group(1))
        weight_kg = float(m.group(2))
        if height_cm < 50 or height_cm > 250 or weight_kg < 10 or weight_kg > 500:
            await event.message.edit("❌ قد باید ۵۰-۲۵۰ و وزن ۱۰-۵۰۰ باشه.", parse_mode=None)
            return True
        height_m = height_cm / 100
        bmi = weight_kg / (height_m ** 2)
        if bmi < 18.5:
            category = "کم‌وزن"
            advice = "🥗 تغذیهٔ بهتر و ورزش قدرتی"
        elif bmi < 25:
            category = "نرمال"
            advice = "✅ عالی! همین رو ادامه بده"
        elif bmi < 30:
            category = "اضافه‌وزن"
            advice = "🏃 ورزش منظم و رژیم متعادل"
        else:
            category = "چاق"
            advice = "⚕️ مشورت با پزشک"
        await event.message.edit(
            f"⚖️ **محاسبه BMI**\n\n"
            f"📏 قد: {height_cm} سانتی‌متر\n"
            f"⚖️ وزن: {weight_kg} کیلوگرم\n\n"
            f"📊 BMI شما: **{bmi:.1f}**\n"
            f"📋 دسته: **{category}**\n\n"
            f"💡 {advice}",
            parse_mode=None,
        )
        return True

    async def cmd_precise_age(self, event, text):
        m = re.match(r"^سن\s+([\d۰-۹]{4})/([\d۰-۹]{1,2})/([\d۰-۹]{1,2})$", text)
        if not m:
            return False
        try:
            year, month, day = int(m.group(1)), int(m.group(2)), int(m.group(3))
            birth = datetime(year, month, day)
            today = datetime.now()
            years = today.year - birth.year - ((today.month, today.day) < (birth.month, birth.day))
            months_total = (today.year - birth.year) * 12 + today.month - birth.month
            if today.day < birth.day:
                months_total -= 1
            days = (today - birth).days
            hours = days * 24
            minutes = hours * 60
            await event.message.edit(
                f"🎂 **سن دقیق**\n\n"
                f"📅 تاریخ تولد: {year}/{month:02d}/{day:02d}\n\n"
                f"⏳ شما **{years} سال** سن دارید.\n"
                f"📆 معادل: {months_total} ماه\n"
                f"📅 معادل: {days} روز\n"
                f"⏰ معادل: {minutes:,} دقیقه",
                parse_mode=None,
            )
        except ValueError:
            await event.message.edit("❌ تاریخ نامعتبره.", parse_mode=None)
        return True

    async def cmd_word_count(self, event, text):
        m = re.match(r"^شمارش کلمات\s+(.+)$", text)
        if not m:
            return False
        content = m.group(1)
        words = content.split()
        chars = len(content)
        chars_no_space = len(content.replace(" ", ""))
        sentences = content.count(".") + content.count("!") + content.count("?")
        lines = content.count("\n") + 1
        await event.message.edit(
            f"📊 **شمارش کلمات**\n\n"
            f"📝 کلمات: **{len(words)}**\n"
            f"🔤 کاراکتر (با فاصله): {chars}\n"
            f"🔡 کاراکتر (بدون فاصله): {chars_no_space}\n"
            f"📄 جملات: {sentences}\n"
            f"📏 خطوط: {lines}",
            parse_mode=None,
        )
        return True

    async def cmd_date_convert(self, event, text):
        m = re.match(r"^تبدیل\s+([\d۰-۹]{4})/([\d۰-۹]{1,2})/([\d۰-۹]{1,2})$", text)
        if not m:
            return False
        try:
            jyear, jmonth, jday = int(m.group(1)), int(m.group(2)), int(m.group(3))
            import jdatetime
            jd = jdatetime.date(jyear, jmonth, jday)
            gd = jd.togregorian()
            # نام روز هفته
            weekdays = ["دوشنبه", "سه‌شنبه", "چهارشنبه", "پنجشنبه", "جمعه", "شنبه", "یکشنبه"]
            wd = weekdays[gd.weekday()]
            await event.message.edit(
                f"📅 **تبدیل تاریخ**\n\n"
                f"🌙 شمسی: {jyear}/{jmonth:02d}/{jday:02d}\n"
                f"☀️ میلادی: {gd.year}/{gd.month:02d}/{gd.day:02d}\n"
                f"📅 روز هفته: {wd}",
                parse_mode=None,
            )
        except Exception:
            await event.message.edit("❌ تاریخ نامعتبره.", parse_mode=None)
        return True

