    async def cmd_calendar_full(self, event, text):
        m = re.match(r"^تقویم\s+([\d۰-۹]{4})$", text)
        if not m:
            return False
        year = int(m.group(1))
        try:
            import jdatetime
            months_fa = ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
                         "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"]
            msg = f"📅 **تقویم {year}**\n\n"
            for m_idx in range(1, 13):
                days_in_month = jdatetime.date(year, m_idx, 1).daysinmonth if hasattr(jdatetime.date(year, m_idx, 1), 'daysinmonth') else 30
                msg += f"**{months_fa[m_idx-1]}:** {days_in_month} روز\n"
            total_days = sum(
                jdatetime.date(year, m, 1).daysinmonth if hasattr(jdatetime.date(year, m, 1), 'daysinmonth') else 30
                for m in range(1, 13)
            )
            msg += f"\n📆 کل روزهای سال: {total_days}"
            await event.message.edit(msg, parse_mode=None)
        except Exception:
            await event.message.edit("❌ خطا در ساخت تقویم.", parse_mode=None)
        return True

