    async def cmd_unit_smart(self, event, text):
        m = re.match(r"^تبدیل\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)\s+(\S+)$", text)
        if not m:
            return False
        amount = float(m.group(1))
        unit = m.group(2)
        conversions = {
            "کیلوگرم": ("گرم", 1000),
            "گرم": ("کیلوگرم", 0.001),
            "کیلومتر": ("متر", 1000),
            "متر": ("سانتی‌متر", 100),
            "سانتی‌متر": ("میلی‌متر", 10),
            "لیتر": ("میلی‌لیتر", 1000),
            "میلی‌لیتر": ("لیتر", 0.001),
            "ساعت": ("دقیقه", 60),
            "دقیقه": ("ثانیه", 60),
        }
        if unit in conversions:
            new_unit, factor = conversions[unit]
            result = amount * factor
            await event.message.edit(
                f"📏 **تبدیل واحد**\n\n"
                f"📊 {amount} {unit}\n"
                f"➜ = **{result:,.2f}** {new_unit}",
                parse_mode=None,
            )
        else:
            await event.message.edit(
                f"❌ واحد «{unit}» پشتیبانی نمیشه.\n\n"
                f"واحدهای موجود: کیلوگرم، گرم، کیلومتر، متر، سانتی‌متر، "
                f"لیتر، میلی‌لیتر، ساعت، دقیقه",
                parse_mode=None,
            )
        return True

    async def cmd_percent_calc(self, event, text):
        m = re.match(r"^درصد\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)\s+از\s+([\d۰-۹]+(?:\.[\d۰-۹]+)?)$", text)
        if not m:
            return False
        percent = float(m.group(1))
        number = float(m.group(2))
        result = (percent * number) / 100
        await event.message.edit(
            f"📊 **محاسبه درصد**\n\n"
            f"🔢 {percent}% از {number}\n"
            f"➜ = **{result:,.2f}**",
            parse_mode=None,
        )
        return True

    async def cmd_password_strong(self, event, text):
        m = re.match(r"^رمز قوی\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        length = int(m.group(1))
        if length < 8 or length > 128:
            await event.message.edit("❌ طول رمز باید ۸ تا ۱۲۸ باشه.", parse_mode=None)
            return True
        chars = string.ascii_letters + string.digits + "!@#$%^&*()_+-=[]{}|;:,.<>?"
        password = ''.join(random.choices(chars, k=length))
        # محاسبهٔ قدرت
        entropy = length * 6.5  # تقریب ساده
        if entropy > 80:
            strength = "💪 بسیار قوی"
        elif entropy > 60:
            strength = "🟢 قوی"
        elif entropy > 40:
            strength = "🟡 متوسط"
        else:
            strength = "🔴 ضعیف"
        await event.message.edit(
            f"🔐 **رمز قوی ساخته شد**\n\n"
            f"🔑 رمز: `{password}`\n\n"
            f"📊 طول: {length} کاراکتر\n"
            f"💪 قدرت: {strength}\n\n"
            f"⚠️ این پیام رو بعد از کپی کردن پاک کن!",
            parse_mode=None,
        )
        return True

    async def cmd_email_check(self, event, text):
        m = re.match(r"^(?:ایمیل|ایمیل معتبره)\s+(\S+@\S+\.\S+)$", text)
        if not m:
            return False
        email = m.group(1)
        # بررسی ساده
        is_valid = bool(re.match(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$", email))
        if is_valid:
            username, domain = email.split("@", 1)
            await event.message.edit(
                f"✅ **ایمیل معتبر است**\n\n"
                f"📧 {email}\n"
                f"👤 نام کاربری: {username}\n"
                f"🌐 دامنه: {domain}",
                parse_mode=None,
            )
        else:
            await event.message.edit(
                f"❌ **ایمیل نامعتبر است**\n\n"
                f"📧 {email}\n\n"
                f"💡 قالب صحیح: name@domain.com",
                parse_mode=None,
            )
        return True

    async def cmd_phone_full(self, event, text):
        m = re.match(r"^شماره\s+(\+?[\d۰-۹]+)$", text)
        if not m:
            return False
        phone = m.group(1)
        # استانداردسازی
        if not phone.startswith("+"):
            phone = "+98" + phone.lstrip("0")
        # بررسی ساده
        is_valid = len(phone) >= 10 and len(phone) <= 15
        if is_valid:
            # تشخیص کشور از پیش‌شماره
            country = "نامشخص"
            if phone.startswith("+98") or phone.startswith("+99"):
                country = "ایران 🇮🇷"
            elif phone.startswith("+1"):
                country = "آمریکا/کانادا 🇺🇸"
            elif phone.startswith("+44"):
                country = "انگلیس 🇬🇧"
            elif phone.startswith("+49"):
                country = "آلمان 🇩🇪"
            elif phone.startswith("+90"):
                country = "ترکیه 🇹🇷"
            await event.message.edit(
                f"✅ **شماره معتبر است**\n\n"
                f"📞 {phone}\n"
                f"🌍 کشور: {country}",
                parse_mode=None,
            )
        else:
            await event.message.edit("❌ شماره نامعتبره (طول باید ۱۰-۱۵ رقم باشه).", parse_mode=None)
        return True

