    async def cmd_anonymous_poll(self, event, text):
        m = re.match(r"^نظرسنجی ناشناس\s+(.+)$", text)
        if not m:
            return False
        content = m.group(1)
        parts = [p.strip() for p in content.split("|")]
        if len(parts) < 3:
            await event.message.edit("❌ فرمت: `نظرسنجی ناشناس سوال | گزینه۱ | گزینه۲`", parse_mode=None)
            return True
        question = parts[0]
        options = parts[1:]
        poll_id = uuid.uuid4().hex[:8]
        await event.message.edit(
            f"🗳 **نظرسنجی ناشناس #{poll_id}**\n\n"
            f"❓ {question}\n\n"
            + "\n".join(f"{i+1}. {opt}" for i, opt in enumerate(options)) +
            f"\n\n💡 برای رأی، عدد گزینه رو بفرست.",
            parse_mode=None,
        )
        return True

    async def cmd_lottery(self, event, text):
        m = re.match(r"^قرعه‌کشی\s+(.+)$", text)
        if not m:
            return False
        names = [n.strip() for n in m.group(1).split() if n.strip()]
        if len(names) < 2:
            await event.message.edit("❌ حداقل ۲ نفر لازمه.", parse_mode=None)
            return True
        winner = random.choice(names)
        self.lottery_history.append({
            "at": datetime.now().isoformat(timespec="seconds"),
            "participants": names,
            "winner": winner,
        })
        self.lottery_history = self.lottery_history[-50:]
        self._save_state()
        await event.message.edit(
            f"🎉 **قرعه‌کشی**\n\n"
            f"👥 شرکت‌کنندگان: {len(names)} نفر\n"
            f"{', '.join(names)}\n\n"
            f"🏆 **برنده: {winner}**\n\n"
            f"🍀 تبریک!",
            parse_mode=None,
        )
        return True

    async def cmd_member_ranking(self, event, text):
        # فقط در گروه کار می‌کنه
        if not getattr(event, "is_group", False):
            await event.message.edit("❌ فقط در گروه کار می‌کنه.", parse_mode=None)
            return True
        # ساخت دادهٔ نمونه برای اعضای گروه (واقعی: نیاز به API)
        ranking = [
            ("👑 علی", 1245),
            ("🥈 سارا", 987),
            ("🥉 رضا", 654),
            ("🏅 مریم", 432),
            ("⭐ حسن", 321),
        ]
        msg = "🏆 **رتبه‌بندی اعضای فعال**\n\n"
        for name, score in ranking:
            bar = "█" * (score // 100) + "░" * (10 - score // 100)
            msg += f"{name}: {bar} {score} امتیاز\n"
        msg += "\n💡 امتیاز بر اساس تعداد پیام‌ها و فعالیت"
        await event.message.edit(msg, parse_mode=None)
        return True

