    async def cmd_make_sticker(self, event, text):
        if not getattr(event, "is_reply", False):
            await event.message.edit("❌ روی یه عکس ریپلای کن.", parse_mode=None)
            return True
        try:
            replied = await event.get_reply_message()
            if not replied.photo:
                await event.message.edit("❌ پیام ریپلای‌شده عکس نیست.", parse_mode=None)
                return True
            # دانلود و تبدیل
            from PIL import Image as PILImage
            path = await replied.download_media(bytes)
            img = PILImage.open(io.BytesIO(path))
            img = img.convert("RGBA").resize((512, 512))
            buf = io.BytesIO()
            img.save(buf, format='WEBP')
            buf.seek(0)
            await event.client.send_file(event.chat_id, buf, force_document=False)
            await event.message.delete()
        except Exception as exc:
            await event.message.edit(f"❌ خطا: {exc}", parse_mode=None)
        return True

