    async def cmd_image_rotate(self, event, text):
        m = re.match(r"^تصویر بچرخ\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        degrees = int(m.group(1))
        if not getattr(event, "is_reply", False):
            await event.message.edit("❌ روی یه عکس ریپلای کن.", parse_mode=None)
            return True
        try:
            replied = await event.get_reply_message()
            if not replied.photo:
                await event.message.edit("❌ پیام ریپلای‌شده عکس نیست.", parse_mode=None)
                return True
            from PIL import Image as PILImage
            path = await replied.download_media(bytes)
            img = PILImage.open(io.BytesIO(path)).convert("RGBA")
            img = img.rotate(-degrees, expand=True)  # منفی چون PIL خلاف جهت می‌چرخه
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            await event.client.send_file(
                event.chat_id,
                buf,
                caption=f"🔄 تصویر {degrees} درجه چرخیده شد",
            )
            await event.message.delete()
        except Exception as exc:
            await event.message.edit(f"❌ خطا: {exc}", parse_mode=None)
        return True

    async def cmd_image_resize(self, event, text):
        m = re.match(r"^تصویر کوچک کن\s+([\d۰-۹]+)$", text)
        if not m:
            return False
        width = int(m.group(1))
        if not getattr(event, "is_reply", False):
            await event.message.edit("❌ روی یه عکس ریپلای کن.", parse_mode=None)
            return True
        try:
            replied = await event.get_reply_message()
            if not replied.photo:
                await event.message.edit("❌ پیام ریپلای‌شده عکس نیست.", parse_mode=None)
                return True
            from PIL import Image as PILImage
            path = await replied.download_media(bytes)
            img = PILImage.open(io.BytesIO(path)).convert("RGBA")
            ratio = width / img.width
            new_height = int(img.height * ratio)
            img = img.resize((width, new_height))
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            await event.client.send_file(
                event.chat_id,
                buf,
                caption=f"📏 تصویر به {width}px تغییر اندازه داده شد",
            )
            await event.message.delete()
        except Exception as exc:
            await event.message.edit(f"❌ خطا: {exc}", parse_mode=None)
        return True

    async def cmd_image_filter(self, event, text):
        m = re.match(r"^تصویر\s+(سیاه سفید|بلور|شارپ)$", text)
        if not m:
            return False
        filter_type = m.group(1)
        if not getattr(event, "is_reply", False):
            await event.message.edit("❌ روی یه عکس ریپلای کن.", parse_mode=None)
            return True
        try:
            replied = await event.get_reply_message()
            if not replied.photo:
                await event.message.edit("❌ پیام ریپلای‌شده عکس نیست.", parse_mode=None)
                return True
            from PIL import Image as PILImage, ImageFilter
            path = await replied.download_media(bytes)
            img = PILImage.open(io.BytesIO(path)).convert("RGBA")
            if filter_type == "سیاه سفید":
                img = img.convert("L").convert("RGBA")
            elif filter_type == "بلور":
                img = img.filter(ImageFilter.BLUR)
            elif filter_type == "شارپ":
                img = img.filter(ImageFilter.SHARPEN)
            buf = io.BytesIO()
            img.save(buf, format='PNG')
            buf.seek(0)
            await event.client.send_file(
                event.chat_id,
                buf,
                caption=f"🎨 فیلتر {filter_type} اعمال شد",
            )
            await event.message.delete()
        except Exception as exc:
            await event.message.edit(f"❌ خطا: {exc}", parse_mode=None)
        return True

