    # ============================================================================
    # ========== ۱۰ قابلیت AI پست (دستهٔ جدید) ==========
    # این متدها با استفاده از API key موجود در self.ai_api_key
    # و get_dialogs تلگرام، محتوای کانال‌ها رو جمع‌آوری و
    # با کمک AI بازنویسی می‌کنن. همچنین جستجوی گوگل هم دارن.
    # ============================================================================

    async def _ai_post_collect_from_channels(self, limit_per_channel=10):
        """جمع‌آوری پست‌های اخیر از کانال‌های منبع.

        اگه ai_post_channels خالی باشه، از همهٔ کانال‌های اکانت می‌گیره.
        """
        collected = []
        try:
            channels = self.ai_post_channels if self.ai_post_channels else []
            # اگه لیست خالیه، از dialogs اکانت استفاده کن
            if not channels:
                async for dialog in self.client.iter_dialogs():
                    entity = dialog.entity
                    if hasattr(entity, "broadcast") and entity.broadcast:  # فقط کانال‌ها
                        channels.append({
                            "title": getattr(entity, "title", "ناشناس"),
                            "username": getattr(entity, "username", None),
                            "id": entity.id,
                        })
                # حداکثر ۵ کانال اول برای شروع
                channels = channels[:5]

            for ch in channels[:10]:  # حداکثر ۱۰ کانال
                try:
                    ch_id = ch.get("id") if isinstance(ch, dict) else ch
                    async for msg in self.client.iter_messages(ch_id, limit=limit_per_channel):
                        if msg and msg.text and len(msg.text) > 20:
                            collected.append({
                                "channel": ch.get("title", "ناشناس") if isinstance(ch, dict) else str(ch),
                                "text": msg.text[:1500],  # افزایش طول برای مادهٔ بیشتر
                                "date": msg.date.isoformat() if msg.date else "",
                            })
                except Exception as exc:
                    logger.warning(f"AI Post: خطا در خواندن کانال {ch}: {exc}")
        except Exception as exc:
            logger.warning(f"AI Post: خطای کلی در جمع‌آوری: {exc}")
        return collected

    async def _ai_post_analyze_channel(self, channel_id, max_posts=50):
        """آنالیز عمیق یک کانال برای فهم ساختار، موضوع، لحن و محتوای تکراری.

        این متد قبل از جمع‌آوری استفاده می‌شه تا بفهمیم:
        - موضوع اصلی کانال چیه
        - لحن و سبک چطوره
        - چه نوع محتوایی داره
        - کدوم پست‌ها مهم و مرتبط هستن
        """
        try:
            # جمع‌آوری تعداد بیشتری پست برای تحلیل دقیق
            all_messages = []
            async for msg in self.client.iter_messages(channel_id, limit=max_posts):
                if msg and msg.text and len(msg.text) > 30:
                    all_messages.append({
                        "id": msg.id,
                        "text": msg.text,
                        "date": msg.date.isoformat() if msg.date else "",
                        "views": getattr(msg, "views", 0) or 0,
                        "forwards": getattr(msg, "forwards", 0) or 0,
                    })
            if not all_messages:
                return None
            # اطلاعات کانال
            try:
                entity = await self.client.get_entity(channel_id)
                channel_info = {
                    "title": getattr(entity, "title", "ناشناس"),
                    "username": getattr(entity, "username", None),
                    "id": channel_id,
                    "about": getattr(entity, "about", "") or "",
                }
            except Exception:
                channel_info = {"id": channel_id, "title": "ناشناس"}
            # آمار پایه
            total_posts = len(all_messages)
            avg_length = sum(len(m["text"]) for m in all_messages) // total_posts
            total_views = sum(m["views"] for m in all_messages)
            avg_views = total_views // total_posts
            # پست‌های پربازدید (top 10)
            top_posts = sorted(all_messages, key=lambda x: x["views"], reverse=True)[:10]
            # نمونه‌های متنوع (پراکنده در زمان)
            samples = []
            if len(all_messages) > 10:
                step = len(all_messages) // 10
                for i in range(0, len(all_messages), step):
                    samples.append(all_messages[i][:500])
            else:
                samples = [m["text"][:500] for m in all_messages]
            # استخراج کلمات کلیدی
            all_text = " ".join(m["text"] for m in all_messages)
            # حذف کلمات ربط فارسی
            stop_words = {"و", "در", "به", "از", "که", "این", "را", "با", "است", "برای", "تا", "یک", "های", "ها", "می", "شود", "بود", "کرد"}
            words = re.findall(r"[\u0600-\u06FF]{3,}", all_text)  # کلمات فارسی ۳ حرف به بالا
            word_freq = Counter([w for w in words if w not in stop_words])
            top_keywords = [w for w, _ in word_freq.most_common(20)]
            # آنالیز AI برای تشخیص موضوع و لحن
            sample_text = "\n\n".join(samples[:5])
            analysis_prompt = (
                "این نمونه‌هایی از یک کانال تلگرام هست. "
                "لطفاً تحلیل کن:\n"
                "1. موضوع اصلی کانال چیست؟ (مثلاً: خبر، سرگرمی، آموزشی، ورزشی، فناوری)\n"
                "2. لحن محتوا چگونه است؟ (رسمی، صمیمی، طنز، علمی، خبری)\n"
                "3. مخاطب هدف چه کسی است؟\n"
                "4. چه نوع محتوایی در آن بیشتر است؟\n"
                "5. ۵ کلمه کلیدی اصلی کانال چیست؟\n\n"
                f"نمونه پست‌ها:\n{sample_text[:3000]}\n\n"
                "پاسخ را به صورت ساختاریافته و کوتاه بده."
            )
            try:
                ai_analysis, _ = await self._ai_chat_text(
                    [
                        {"role": "system", "content": "تو یه تحلیلگر محتوای فارسی هستی."},
                        {"role": "user", "content": analysis_prompt},
                    ],
                    max_tokens=500
                )
            except Exception as exc:
                logger.warning(f"AI Post: خطا در تحلیل AI: {exc}")
                ai_analysis = None
            return {
                "channel_info": channel_info,
                "total_posts": total_posts,
                "avg_length": avg_length,
                "avg_views": avg_views,
                "top_keywords": top_keywords,
                "top_posts": [{"text": p["text"][:500], "views": p["views"]} for p in top_posts],
                "samples": samples,
                "ai_analysis": ai_analysis,
                "all_messages": all_messages,  # برای استفاده در فیلتر
            }
        except Exception as exc:
            logger.error(f"AI Post: خطا در آنالیز کانال {channel_id}: {exc}")
            return None

    async def _ai_post_smart_collect(self, target_topic=None, min_relevance=0.6):
        """جمع‌آوری هوشمند با تحلیل و فیلتر محتوای مرتبط.

        برخلاف روش قدیم که فقط چند پست آخر رو می‌گرفت، این متد:
        ۱. هر کانال رو جداگانه آنالیز می‌کنه
        ۲. محتوای مرتبط با موضوع رو فیلتر می‌کنه
        ۳. از همه پست‌ها (نه فقط اخیر) استخراج می‌کنه
        ۴. پست‌های پربازدید و مهم رو اولویت می‌ده
        """
        self._init_extension_state()
        config = self.ai_post_config
        if not target_topic:
            target_topic = config.get("topic") or config.get("search_query")
        if not target_topic:
            logger.warning("AI Post smart_collect: target_topic مشخص نیست")
            return []
        target_topic = target_topic.strip()
        channels = self.ai_post_channels if self.ai_post_channels else []
        if not channels:
            # از dialogs
            async for dialog in self.client.iter_dialogs():
                entity = dialog.entity
                if hasattr(entity, "broadcast") and entity.broadcast:
                    channels.append({
                        "title": getattr(entity, "title", "ناشناس"),
                        "username": getattr(entity, "username", None),
                        "id": entity.id,
                    })
            channels = channels[:5]
        if not channels:
            return []
        all_relevant_posts = []
        channel_analyses = {}  # برای debug
        for ch in channels[:10]:
            ch_id = ch.get("id") if isinstance(ch, dict) else ch
            try:
                # مرحله ۱: آنالیز کانال
                analysis = await self._ai_post_analyze_channel(ch_id, max_posts=50)
                if not analysis:
                    continue
                channel_analyses[ch_id] = {
                    "title": analysis["channel_info"].get("title", "?"),
                    "total_posts": analysis["total_posts"],
                    "avg_views": analysis["avg_views"],
                    "ai_summary": analysis.get("ai_analysis", "")[:200] if analysis.get("ai_analysis") else "",
                    "top_keywords": analysis["top_keywords"][:5],
                }
                # مرحله ۲: فیلتر پست‌های مرتبط با موضوع
                relevant_posts = []
                for msg in analysis["all_messages"]:
                    relevance = await self._ai_post_check_relevance(
                        msg["text"], target_topic, analysis
                    )
                    if relevance >= min_relevance:
                        relevant_posts.append({
                            "channel": analysis["channel_info"].get("title", "?"),
                            "channel_id": ch_id,
                            "text": msg["text"][:2000],
                            "date": msg["date"],
                            "views": msg.get("views", 0),
                            "relevance": relevance,
                        })
                # مرحله ۳: مرتب‌سازی (مرتبط‌ترین + پربازدیدترین)
                relevant_posts.sort(key=lambda x: (x["relevance"], x["views"]), reverse=True)
                # فقط top 5 از هر کانال
                all_relevant_posts.extend(relevant_posts[:5])
            except Exception as exc:
                logger.warning(f"AI Post: خطا در smart_collect برای کانال {ch_id}: {exc}")
        # ذخیره تحلیل‌ها برای نمایش
        config["last_channel_analyses"] = channel_analyses
        # مرتب‌سازی نهایی بر اساس relevance
        all_relevant_posts.sort(key=lambda x: x["relevance"], reverse=True)
        return all_relevant_posts

    async def _ai_post_check_relevance(self, text, topic, channel_analysis=None):
        """بررسی میزان ارتباط یک پست با موضوع مورد نظر.

        با cache برای جلوگیری از فراخوانی‌های تکراری AI.

        خروجی: امتیاز بین ۰ تا ۱
        """
        global _relevance_cache
        try:
            _relevance_cache
        except NameError:
            _relevance_cache = {}
        # hash متن + موضوع برای cache
        import hashlib
        cache_key = hashlib.md5(
            (text[:500] + "|" + topic).encode("utf-8", errors="ignore")
        ).hexdigest()
        if cache_key in _relevance_cache:
            return _relevance_cache[cache_key]
        try:
            # روش سریع: چک کلمات کلیدی
            topic_words = set(re.findall(r"[\u0600-\u06FF]{3,}", topic))
            text_words = set(re.findall(r"[\u0600-\u06FF]{3,}", text))
            if topic_words:
                keyword_overlap = len(topic_words & text_words) / len(topic_words)
            else:
                keyword_overlap = 0
            # اگه overlap خیلی بالا یا خیلی پایینه، سریع برگردون (بدون AI)
            if keyword_overlap >= 0.7:
                result = min(0.95, 0.7 + keyword_overlap * 0.3)
                _relevance_cache[cache_key] = result
                return result
            if keyword_overlap < 0.2:
                result = keyword_overlap * 0.5
                _relevance_cache[cache_key] = result
                return result
            # برای موارد متوسط (0.2-0.7)، از AI بپرس ولی با context کمتر
            context = ""
            if channel_analysis and channel_analysis.get("ai_analysis"):
                # فقط ۱۰۰ کاراکتر اول context
                context = f"کانال: {channel_analysis['ai_analysis'][:100]}\n"
            prompt = (
                f"موضوع: «{topic}»\n"
                f"{context}"
                f"پست: {text[:500]}\n"
                "فقط یک عدد بین 0.0 تا 1.0:"
            )
            try:
                answer, _ = await self._ai_chat_text(
                    [
                        {"role": "system", "content": "فقط عدد برگردون. مثال: 0.85"},
                        {"role": "user", "content": prompt},
                    ],
                    max_tokens=5  # خیلی کم، فقط عدد
                )
                if answer:
                    match = re.search(r"0?\.\d+|[01]\.?\d*", answer)
                    if match:
                        result = max(0.0, min(1.0, float(match.group())))
                        _relevance_cache[cache_key] = result
                        return result
            except Exception as exc:
                logger.warning(f"AI Post: خطا در AI relevance: {exc}")
            # fallback به keyword
            _relevance_cache[cache_key] = keyword_overlap
            return keyword_overlap
        except Exception as exc:
            logger.warning(f"AI Post: خطا در relevance check: {exc}")
            return 0.5

    async def _ai_post_google_search(self, query, num_results=5):
        """جستجوی گوگل و استخراج نتایج.

        با cache، rate limit داخلی، و User-Agent واقعی.
        اگه scrape شکست بخوره، fallback به داده نمونه می‌کنه.
        """
        global _google_search_cache
        try:
            _google_search_cache
        except NameError:
            _google_search_cache = {}
        # چک cache - فقط ۵ دقیقه اعتبار داره
        cache_key = f"{query}:{num_results}"
        if cache_key in _google_search_cache:
            cached_result, cached_time = _google_search_cache[cache_key]
            if time.time() - cached_time < 300:
                return cached_result
        results = []
        try:
            import urllib.request
            import urllib.parse
            import urllib.error
            import socket
            socket.setdefaulttimeout(15)
            url = f"https://www.google.com/search?q={urllib.parse.quote(query)}&hl=fa&num={num_results * 2}"
            req = urllib.request.Request(url, headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/121.0.0.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8",
                "Accept-Language": "fa-IR,fa;q=0.9,en-US;q=0.8,en;q=0.7",
                "Accept-Encoding": "gzip, deflate",
                "DNT": "1",
                "Connection": "keep-alive",
                "Upgrade-Insecure-Requests": "1",
            })
            with urllib.request.urlopen(req, timeout=15) as response:
                if response.headers.get("Content-Encoding") == "gzip":
                    import gzip
                    html = gzip.decompress(response.read()).decode("utf-8", errors="ignore")
                else:
                    html = response.read().decode("utf-8", errors="ignore")
                import re as re_mod
                titles = re_mod.findall(r"<h3[^>]*>([^<]{10,200})</h3>", html)
                snippets = re_mod.findall(r'class="VwiC3b[^"]*"[^>]*>([^<]{30,400})</span>', html)
                if not snippets:
                    snippets = re_mod.findall(r"<span[^>]*>([^<]{30,400})</span>", html)
                for i, title in enumerate(titles[:num_results]):
                    snippet = snippets[i] if i < len(snippets) else ""
                    title_clean = re_mod.sub(r"<[^>]+>", "", title).strip()
                    snippet_clean = re_mod.sub(r"<[^>]+>", "", snippet).strip()
                    if title_clean:
                        results.append(f"{title_clean}: {snippet_clean[:300]}")
                if not results and snippets:
                    results = [re_mod.sub(r"<[^>]+>", "", s).strip()[:300] for s in snippets[:num_results]]
            _google_search_cache[cache_key] = (results, time.time())
        except (urllib.error.URLError, TimeoutError, socket.timeout) as exc:
            logger.warning(f"AI Post: جستجوی گوگل ناموفق (شبکه): {type(exc).__name__}")
            results = [
                f"📰 جستجوی گوگل برای «{query}» - اتصال برقرار نشد.",
                f"💡 پیشنهاد: VPN یا کوئری کوتاه‌تر.",
            ]
        except Exception as exc:
            logger.exception(f"AI Post: جستجوی گوگل خطا: {exc}")
            results = [
                f"جستجوی گوگل برای «{query}»: خطا. دوباره تلاش کن.",
            ]
        return results

    async def _ai_post_professional_edit(self, raw_posts, search_results, config):
        """ادیت حرفه‌ای پست‌ها با AI - این مرحلهٔ کلیدی کاره.

        AI باید:
        ۱. محتوای خام کانال‌ها رو بگیره
        ۲. با لحن و سبک مناسب بازنویسی کنه
        ۳. از نتایج گوگل برای غنی‌سازی استفاده کنه
        ۴. خروجی کاملاً یکتا و حرفه‌ای بده
        """
        length_map = {
            "کوتاه": "بین ۱۵۰ تا ۲۵۰ کاراکتر (فشرده و مؤثر)",
            "متوسط": "بین ۳۰۰ تا ۵۰۰ کاراکتر (متعادل)",
            "بلند": "بین ۶۰۰ تا ۹۰۰ کاراکتر (تحلیلی و کامل)",
        }
        tone = config.get("tone", "صمیمی و حرفه‌ای")
        length = config.get("length", "متوسط")
        topic = config.get("topic", "عمومی")
        length_hint = length_map.get(length, length_map["متوسط"])

        # ساخت مادهٔ خام از کانال‌ها
        channel_material = ""
        for i, p in enumerate(raw_posts[:15], 1):
            channel_material += f"\n\n[پست #{i} از کانال «{p['channel']}»]\n{p['text'][:800]}"

        # ساخت مادهٔ گوگل
        google_material = ""
        if search_results:
            google_material = "\n\n[اطلاعات تکمیلی از جستجوی گوگل]\n"
            for i, s in enumerate(search_results[:5], 1):
                google_material += f"\n{i}. {s[:400]}"

        # Prompt حرفه‌ای - اینجاست که جادو می‌شه
        system_prompt = (
            "تو یه ویراستار و نویسندهٔ حرفه‌ای محتوای فارسی هستی برای کانال تلگرام.\n"
            "وظیفه‌ات:\n"
            "۱. از محتوای کانال‌ها، نکات کلیدی و مهم رو استخراج کن\n"
            "۲. اگه اطلاعات تکمیلی از گوگل موجوده، اون رو هم اضافه کن\n"
            "۳. متن رو به صورت کاملاً بازنویسی شده و یکتا ارائه بده (نه کپی)\n"
            "۴. لحن و سبک رو حرفه‌ای و قابل خواندن کن\n"
            "۵. ساختار منظم داشته باش (پاراگراف‌بندی، ایموجی مناسب، خوانایی بالا)\n"
            "۶. در انتها اگه منطقیه، ۳ تا ۵ هشتگ مرتبط اضافه کن\n\n"
            f"لحن مورد نظر: {tone}\n"
            f"طول مورد نظر: {length_hint}\n"
            f"موضوع اصلی: {topic}\n"
        )

        user_prompt = (
            f"محتوای زیر از کانال‌های تلگرام جمع‌آوری شده:{channel_material}{google_material}\n\n"
            "لطفاً:\n"
            f"• یه پست تلگرامی حرفه‌ای، یکتا و جذاب بنویس\n"
            f"• موضوع اصلی: «{topic}»\n"
            f"• لحن: {tone}\n"
            f"• طول: {length_hint}\n"
            "• از ایموجی مناسب برای خوانایی بهتر استفاده کن\n"
            "• اگه اطلاعات تکمیلی از گوگل داری، حتماً ترکیبش کن\n"
            "• ۳ تا ۵ هشتگ مرتبط در انتها اضافه کن\n"
            "• متن نهایی نباید کپی مستقیم باشه؛ باید کاملاً بازنویسی شده و یکتا باشه"
        )

        try:
            answer, error = await self._ai_chat_text([
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ], max_tokens=1500)  # بیشتر برای پست‌های بلند
            if answer:
                return answer, None
            return None, error or "AI جواب نداد"
        except Exception as exc:
            return None, f"خطا در فراخوانی AI: {exc}"

    async def _ai_post_full_pipeline(self, event, query="آخرین موضوع داغ"):
        """پایپ‌لاین کامل: جمع‌آوری → ادیت حرفه‌ای → انتشار.

        این متد اصلی‌ترین متده که همه کار رو یکجا انجام می‌ده:
        ۱. از کانال‌های منبع پست جمع می‌کنه
        ۲. اگه موضوع مشخص باشه، گوگل هم می‌زنه
        ۳. همه رو با AI حرفه‌ای ادیت می‌کنه
        ۴. منتشر می‌کنه
        """
        self._init_extension_state()
        config = self.ai_post_config
        # اگه topic در config نبود، از query استفاده کن
        if not config.get("topic"):
            config["topic"] = query
        if not config.get("search_query") and query:
            config["search_query"] = query

        await event.message.edit(
            "🔄 **در حال اجرای پایپ‌لاین کامل AI پست...**\n\n"
            "├ مرحله ۱/۳: جمع‌آوری از کانال‌ها 📥\n"
            "├ مرحله ۲/۳: جستجوی گوگل + ادیت حرفه‌ای 🤖\n"
            "└ مرحله ۳/۳: انتشار 📤",
            parse_mode=None,
        )

        # مرحله ۱: جمع‌آوری از کانال‌ها
        try:
            collected = await self._ai_post_collect_from_channels(limit_per_channel=8)
        except Exception as exc:
            await event.message.edit(f"❌ خطا در جمع‌آوری: {exc}", parse_mode=None)
            return True

        if not collected:
            await event.message.edit(
                "❌ **هیچ پستی از کانال‌ها جمع نشد**\n\n"
                "💡 چک کن:\n"
                "• ربات در کانال‌ها عضو باشه\n"
                "• کانال‌ها پست متنی داشته باشن\n"
                "• `پست AI کانال + @channel` رو بزن",
                parse_mode=None,
            )
            return True

        await event.message.edit(
            f"📥 **جمع‌آوری شد:** {len(collected)} پست از {len(self.ai_post_channels) or '?'} کانال\n\n"
            "🤖 **در حال جستجوی گوگل و ادیت حرفه‌ای...**",
            parse_mode=None,
        )

        # مرحله ۲: جستجوی گوگل + ادیت
        search_results = []
        if query:
            try:
                search_results = await self._ai_post_google_search(query, num_results=5)
            except Exception as exc:
                logger.warning(f"AI Post: جستجوی گوگل در pipeline ناموفق: {exc}")

        # ادیت حرفه‌ای با AI
        if not await self._ai_available():
            await event.message.edit(
                "❌ **API key تنظیم نشده**\n\n"
                "💡 با فرمان `تنظیم کلید [کلید]` کلید API رو تنظیم کن.",
                parse_mode=None,
            )
            return True

        post_text, error = await self._ai_post_professional_edit(
            collected, search_results, config
        )

        if not post_text:
            await event.message.edit(
                f"❌ **خطا در ادیت حرفه‌ای:**\n\n`{error}`",
                parse_mode=None,
            )
            return True

        # ذخیره draft
        draft_id = len(self.ai_post_drafts) + 1
        self.ai_post_drafts.append({
            "id": draft_id,
            "text": post_text,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "topic": config.get("topic", ""),
            "sources": len(collected),
            "google_results": len(search_results),
        })
        self.ai_post_drafts = self.ai_post_drafts[-50:]

        # مرحله ۳: انتشار خودکار
        try:
            await self.client.send_message(event.chat_id, post_text, parse_mode=None)
            # ثبت در تاریخچه
            self.ai_post_history.append({
                "draft_id": draft_id,
                "published_at": datetime.now().isoformat(timespec="seconds"),
                "chat_id": str(event.chat_id),
                "auto": True,
            })
            self.ai_post_history = self.ai_post_history[-200:]
            self.ai_post_stats_log.append({
                "type": "auto_publish",
                "at": datetime.now().isoformat(timespec="seconds"),
                "topic": config.get("topic", ""),
            })
            self.ai_post_config["last_published"] = time.time()
            self._save_state()
            await event.message.edit(
                f"✅ **پست حرفه‌ای منتشر شد!**\n\n"
                f"📊 **خلاصهٔ فرآیند:**\n"
                f"├ پست‌های جمع‌آوری‌شده: {len(collected)}\n"
                f"├ نتایج گوگل: {len(search_results)}\n"
                f"├ شمارهٔ پست: #{draft_id}\n"
                f"└ زمان: {datetime.now().strftime('%H:%M:%S')}\n\n"
                f"💡 پست بالا منتشر شد.",
                parse_mode=None,
            )
        except Exception as exc:
            await event.message.edit(
                f"⚠️ **پست ساخته شد ولی انتشار ناموفق:**\n\n`{exc}`\n\n"
                f"📝 شمارهٔ draft: #{draft_id}\n"
                f"💡 با `پست AI انتشار` دوباره تلاش کن.",
                parse_mode=None,
            )
        return True

