    async def cmd_ai_post_set_target(self, event, text):
        """تنظیم مقصد انتشار پست‌ها.

        استفاده:
        - روی پیام کانال/گروه مقصد ریپلای کن و بگو `پست AI مقصد`
        - یا `پست AI مقصد @channel_name`
        - یا `پست AI مقصد 123456789` (chat_id)
        """
        self._init_extension_state()
        config = self.ai_post_config
        target = None
        target_title = ""

        # حالت ۱: ریپلای روی یک پیام
        if getattr(event, "is_reply", False):
            try:
                replied = await event.get_reply_message()
                if replied:
                    # استخراج chat_id - ممکنه چند جا باشه
                    # برای پیام‌های کانال: peer_id یا fwd_from
                    # برای پیام‌های گروه: chat_id
                    # برای پیام‌های PV: sender_id
                    target = getattr(replied, "chat_id", None)
                    if not target or target == 0:
                        # امتحان روش‌های دیگر
                        peer_id = getattr(replied, "peer_id", None)
                        if peer_id:
                            try:
                                # peer_id ممکنه user, chat, یا channel باشه
                                target = peer_id.channel_id or peer_id.chat_id or peer_id.user_id
                            except AttributeError:
                                target = None
                    if not target:
                        # روش آخر: استفاده از chat entity
                        chat = getattr(replied, "chat", None)
                        if chat:
                            target = getattr(chat, "id", None)
                    # استخراج عنوان
                    if hasattr(replied, "sender") and replied.sender:
                        target_title = getattr(replied.sender, "title", "") or \
                                       getattr(replied.sender, "first_name", "")
                    elif hasattr(replied, "chat") and replied.chat:
                        target_title = getattr(replied.chat, "title", "") or \
                                       getattr(replied.chat, "first_name", "")
                    if not target_title and hasattr(replied, "sender_id"):
                        target_title = f"Chat {target or '?'}"
            except Exception as exc:
                logger.warning(f"AI Post: خطا در دریافت ریپلای: {exc}")

        # حالت ۲: @channel_name یا chat_id از خود فرمان
        if target is None:
            # ممکنه فرمان چیزی بعد از "پست AI مقصد" داشته باشه
            m = re.match(r"^پست AI مقصد\s+(@?\S+)$", text)
            if m:
                ref = m.group(1).strip()
                # حذف @ اگه اولش باشه
                if ref.startswith("@"):
                    ref = ref[1:]
                try:
                    # امتحان اول: get_entity
                    entity = await self.client.get_entity(ref)
                    target = entity.id
                    target_title = getattr(entity, "title", ref)
                except Exception as exc:
                    # fallback: استفاده مستقیم از username
                    try:
                        # ممکنه numeric ID باشه
                        if ref.lstrip("-").isdigit():
                            target = int(ref)
                            target_title = f"ID: {ref}"
                        else:
                            await event.message.edit(
                                f"❌ **خطا در پیدا کردن مقصد:**\n\n`{exc}`\n\n"
                                "💡 روش‌های تنظیم:\n"
                                "1. روی پیام کانال ریپلای کن و بگو `پست AI مقصد`\n"
                                "2. `پست AI مقصد @channel_name`\n"
                                "3. `پست AI مقصد -1001234567890` (chat_id عددی)\n"
                                "4. مطمئن شو ربات عضو/ادمین کانال مقصد هست",
                                parse_mode=None,
                            )
                            return True
                    except Exception:
                        await event.message.edit(
                            f"❌ **خطا:**\n\n`{exc}`\n\n"
                            "💡 روش‌های تنظیم رو در `پست AI تنظیم` ببین.",
                            parse_mode=None,
                        )
                        return True

        if target is None:
            # پیش‌فرض: همین چت
            target = event.chat_id
            target_title = "همین چت"

        # اعتبارسنجی نهایی
        if not isinstance(target, int) or target == 0:
            await event.message.edit(
                f"❌ **مقصد نامعتبر:**\n\n"
                f"شناسه: `{target}`\n\n"
                f"💡 روش‌های دیگر رو امتحان کن.",
                parse_mode=None,
            )
            return True

        # ذخیره
        config["target_chat_id"] = target
        config["target_chat_title"] = target_title or f"Chat {target}"
        self._save_state()

        # نمایش فارسی شناسه
        target_display = _to_persian_digits(str(target))

        await event.message.edit(
            f"📍 **مقصد انتشار تنظیم شد**\n\n"
            f"🎯 نام: {config['target_chat_title']}\n"
            f"🆔 شناسه: `{target_display}`\n\n"
            f"💡 **از این به بعد، همهٔ پست‌های AI اینجا ارسال میشن.**\n\n"
            f"📊 **سایر تنظیمات:**\n"
            f"├ `پست AI فاصله` — تنظیم فاصلهٔ زمانی\n"
            f"├ `پست AI سری 5` — ارسال ۵ پست پشت سر هم",
            parse_mode=None,
        )
        return True

    async def cmd_ai_post_set_interval(self, event, text):
        """تنظیم فاصلهٔ زمانی بین پست‌ها در حالت سری.

        استفاده:
        - `پست AI فاصله 3 دقیقه`
        - `پست AI فاصله 30 ثانیه`
        - `پست AI فاصله 2 ساعت`
        """
        m = re.match(r"^پست AI فاصله(?:\s+([\d۰-۹]+)\s+(دقیقه|ثانیه|ساعت))?$", text)
        if not m:
            await event.message.edit(
                "⏱ **تنظیم فاصلهٔ زمانی بین پست‌ها**\n\n"
                "💡 **نمونه‌ها:**\n"
                "├ `پست AI فاصله 3 دقیقه` — هر ۳ دقیقه\n"
                "├ `پست AI فاصله 30 ثانیه` — هر ۳۰ ثانیه\n"
                "├ `پست AI فاصله 2 ساعت` — هر ۲ ساعت\n\n"
                "⚠️ **حداقل ۱۰ ثانیه** (برای جلوگیری از spam)\n"
                "⚠️ **حداکثر ۲۴ ساعت**",
                parse_mode=None,
            )
            return True
        if not m.group(1):
            # نمایش مقدار فعلی
            self._init_extension_state()
            current = self.ai_post_config.get("batch_interval_min", 60)
            await event.message.edit(
                f"⏱ **فاصلهٔ فعلی:** هر {current} دقیقه\n\n"
                f"💡 برای تغییر:\n"
                f"`پست AI فاصله 5 دقیقه`\n"
                f"`پست AI فاصله 30 ثانیه`",
                parse_mode=None,
            )
            return True

        value = int(m.group(1))
        unit = m.group(2)
        if unit == "ثانیه":
            minutes = value / 60.0
            if minutes < 0.167 or minutes > 1440:
                await event.message.edit("❌ فاصله باید بین ۱۰ ثانیه تا ۱۴۴۰ دقیقه (۲۴ ساعت) باشه.", parse_mode=None)
                return True
        elif unit == "دقیقه":
            minutes = value
            if minutes < 0.167 or minutes > 1440:
                await event.message.edit("❌ فاصله باید بین ۰.۱۶۷ تا ۱۴۴۰ دقیقه باشه.", parse_mode=None)
                return True
        else:  # ساعت
            minutes = value * 60
            if minutes < 0.167 or minutes > 1440:
                await event.message.edit("❌ فاصله باید بین ۰.۱۶۷ تا ۲۴ ساعت باشه.", parse_mode=None)
                return True

        self._init_extension_state()
        self.ai_post_config["batch_interval_min"] = minutes
        self._save_state()

        unit_fa = "ثانیه" if unit == "ثانیه" else "دقیقه" if unit == "دقیقه" else "ساعت"
        await event.message.edit(
            f"⏱ **فاصله تنظیم شد**\n\n"
            f"📊 هر **{value} {unit_fa}** یه پست ارسال میشه.\n"
            f"💡 برای استفاده: `پست AI سری [تعداد]`\n\n"
            f"📌 **نکته مهم:** فاصله فقط برای ارسال‌های متوالی (سری) استفاده میشه.",
            parse_mode=None,
        )
        return True

    async def cmd_ai_post_batch(self, event, text):
        """شروع ارسال سری پست‌ها پشت سر هم با فاصلهٔ زمانی.

        مثلاً: `پست AI سری 5` یعنی ۵ پست حرفه‌ای پشت سر هم با فاصلهٔ تنظیم‌شده.
        """
        m = re.match(r"^پست AI سری\s+(\d+)$", text)
        if not m:
            return False
        count = int(m.group(1))
        if count < 1 or count > 50:
            await event.message.edit("❌ تعداد باید بین ۱ تا ۵۰ باشه.", parse_mode=None)
            return True

        self._init_extension_state()
        # بازیابی state اگه ری‌استارت شده
        _recover_batch_state(self)

        config = self.ai_post_config
        if not await self._ai_available():
            await event.message.edit("❌ API key تنظیم نشده. با `تنظیم کلید [کلید]` تنظیم کن.", parse_mode=None)
            return True
        # اگه سری قبلی فعاله، اجازه نده
        if config.get("batch_active", False):
            await event.message.edit(
                "⚠️ **سری دیگری در حال اجراست!**\n\n"
                "💡 اول با `پست AI توقف سری` اون رو متوقف کن.",
                parse_mode=None,
            )
            return True

        target = config.get("target_chat_id") or event.chat_id
        target_title = config.get("target_chat_title") or "همین چت"
        interval = config.get("batch_interval_min", 60)
        topic = config.get("topic") or config.get("search_query") or "اخبار و موضوعات داغ"

        # علامت‌گذاری سری فعال
        config["batch_active"] = True
        config["batch_size"] = count
        config["batch_total_sent"] = 0
        config["batch_target_total"] = count
        # ذخیرهٔ زمان شروع برای recovery
        config["batch_started_at"] = time.time()
        self._save_state()

        # تبدیل interval به نمایش فارسی
        if interval < 1:
            interval_display = f"{int(interval * 60)} ثانیه"
        elif interval < 60:
            interval_display = f"{int(interval)} دقیقه"
        else:
            interval_display = f"{interval / 60:.1f} ساعت"

        await event.message.edit(
            f"🚀 **سری پست شروع شد!**\n\n"
            f"📊 **پارامترها:**\n"
            f"├ تعداد: {count} پست\n"
            f"├ فاصله: هر {interval_display}\n"
            f"├ مقصد: {target_title}\n"
            f"├ موضوع: {topic}\n\n"
            f"⏳ **در حال ساخت و ارسال...**\n"
            f"(پست اول فوری، بقیه با فاصله)",
            parse_mode=None,
        )

        # پست اول فوری
        try:
            # جمع‌آوری + جستجو + ادیت
            collected = await self._ai_post_collect_from_channels(limit_per_channel=8)
            search_results = []
            if topic:
                try:
                    search_results = await self._ai_post_google_search(topic, num_results=5)
                except Exception as exc:
                    logger.warning(f"AI Post: گوگل در batch ناموفق: {exc}")
            post_text, error = await self._ai_post_professional_edit(
                collected, search_results, config
            )
            if not post_text:
                await event.message.edit(f"❌ خطا در ساخت پست اول: {error}", parse_mode=None)
                config["batch_active"] = False
                self._save_state()
                return True

            # ارسال پست اول با safe_send
            sent_msg = await _safe_send_message(
                self.client, target, post_text, parse_mode=None
            )
            if sent_msg is None:
                raise RuntimeError("ارسال ناموفق بعد از چند تلاش")
            config["batch_total_sent"] = 1
            self.ai_post_history.append({
                "draft_id": len(self.ai_post_drafts) + 1,
                "published_at": datetime.now().isoformat(timespec="seconds"),
                "chat_id": str(target),
                "auto": True,
                "batch": True,
            })
            self.ai_post_drafts.append({
                "id": len(self.ai_post_drafts) + 1,
                "text": post_text,
                "created_at": datetime.now().isoformat(timespec="seconds"),
                "topic": topic,
                "sources": len(collected),
            })
            self.ai_post_stats_log.append({
                "type": "publish",
                "at": datetime.now().isoformat(timespec="seconds"),
                "batch": True,
            })
            self._save_state()

            if count == 1:
                config["batch_active"] = False
                self._save_state()
                await event.message.edit(
                    f"✅ **سری کامل شد!**\n\n"
                    f"📊 {count}/{count} پست ارسال شد.",
                    parse_mode=None,
                )
                return True

            # بقیه پست‌ها با فاصله - ذخیره task reference
            ext_state = _get_extension_state(self)
            ext_state["batch_active"] = True
            task = asyncio.create_task(
                self._ai_post_batch_send(count, interval, target, topic)
            )
            ext_state["batch_task"] = task
            await event.message.edit(
                f"✅ **پست ۱ از {count} ارسال شد**\n\n"
                f"⏰ پست بعدی: {interval_display} دیگر\n"
                f"💡 برای توقف: `پست AI توقف سری`",
                parse_mode=None,
            )
        except Exception as exc:
            logger.exception(f"AI Post: خطا در شروع batch: {exc}")
            config["batch_active"] = False
            ext_state = _get_extension_state(self)
            ext_state["batch_active"] = False
            ext_state["batch_task"] = None
            self._save_state()
            await event.message.edit(f"❌ خطا: {exc}", parse_mode=None)
        return True

    async def _ai_post_batch_send(self, total, interval_minutes, target, topic):
        """ارسال بقیه پست‌های سری با فاصلهٔ زمانی در پس‌زمینه.

        با safe send برای مدیریت FloodWait.
        با state recovery اگه ربات ری‌استارت بشه.
        """
        self._init_extension_state()
        config = self.ai_post_config
        ext_state = _get_extension_state(self)

        # تبدیل interval به ثانیه
        interval_seconds = interval_minutes * 60
        sent = config.get("batch_total_sent", 1)

        for i in range(sent, total):
            # چک توقف
            if not config.get("batch_active", False):
                logger.info(f"AI Post batch: سری توسط کاربر متوقف شد (پست {i}/{total})")
                return
            # صبر کن (با چک دوره‌ای برای توقف)
            # هر ۱۰ ثانیه چک کن، نه یک sleep طولانی
            slept = 0
            while slept < interval_seconds:
                if asyncio.current_task() and asyncio.current_task().cancelled():
                    return
                if not config.get("batch_active", False):
                    return
                chunk = min(10, interval_seconds - slept)
                await asyncio.sleep(chunk)
                slept += chunk
            # چک دوباره بعد از خواب
            if not config.get("batch_active", False):
                return
            try:
                collected = await self._ai_post_collect_from_channels(limit_per_channel=8)
                search_results = []
                if topic:
                    try:
                        search_results = await self._ai_post_google_search(topic, num_results=5)
                    except Exception as exc:
                        logger.warning(f"AI Post batch: گوگل ناموفق: {exc}")
                post_text, error = await self._ai_post_professional_edit(
                    collected, search_results, config
                )
                if not post_text:
                    logger.warning(f"AI Post batch: خطا در ساخت پست {i+1}: {error}")
                    continue
                # ارسال امن
                sent_msg = await _safe_send_message(
                    self.client, target, post_text, parse_mode=None
                )
                if sent_msg is None:
                    logger.warning(f"AI Post batch: ارسال پست {i+1} ناموفق")
                    continue
                config["batch_total_sent"] = i + 1
                self.ai_post_history.append({
                    "draft_id": len(self.ai_post_drafts) + 1,
                    "published_at": datetime.now().isoformat(timespec="seconds"),
                    "chat_id": str(target),
                    "auto": True,
                    "batch": True,
                })
                self.ai_post_drafts.append({
                    "id": len(self.ai_post_drafts) + 1,
                    "text": post_text,
                    "created_at": datetime.now().isoformat(timespec="seconds"),
                    "topic": topic,
                    "sources": len(collected),
                })
                self.ai_post_stats_log.append({
                    "type": "publish",
                    "at": datetime.now().isoformat(timespec="seconds"),
                    "batch": True,
                })
                self._save_state()
                logger.info(f"AI Post batch: پست {i+1}/{total} ارسال شد")
            except asyncio.CancelledError:
                logger.info("AI Post batch: task لغو شد")
                return
            except Exception as exc:
                logger.exception(f"AI Post batch: خطا در ارسال پست {i+1}: {exc}")
        # پایان سری
        config["batch_active"] = False
        ext_state["batch_active"] = False
        ext_state["batch_task"] = None
        self._save_state()
        logger.info(f"AI Post batch: سری کامل شد ({total} پست)")

    async def cmd_ai_post_batch_stop(self, event, text):
        """توقف سری پست‌های در حال ارسال."""
        self._init_extension_state()
        _recover_batch_state(self)
        config = self.ai_post_config
        ext_state = _get_extension_state(self)

        if not config.get("batch_active", False) and not ext_state.get("batch_active", False):
            await event.message.edit("ℹ️ سری فعالی نیست.", parse_mode=None)
            return True
        sent = config.get("batch_total_sent", 0)
        target_total = config.get("batch_target_total", 0)
        # غیرفعال کردن در هر دو جا
        config["batch_active"] = False
        ext_state["batch_active"] = False
        # لغو task اگه فعاله
        task = ext_state.get("batch_task")
        if task and not task.done():
            task.cancel()
            try:
                await task
            except (asyncio.CancelledError, Exception):
                pass
        ext_state["batch_task"] = None
        self._save_state()
        await event.message.edit(
            f"⏹ **سری متوقف شد**\n\n"
            f"📊 ارسال‌شده: {sent}/{target_total} پست\n"
            f"⏸ بقیه ارسال نمیشن.",
            parse_mode=None,
        )
        return True

    async def cmd_ai_post_add_channel(self, event, text):
        """افزودن یا حذف کانال منبع."""
        m = re.match(r"^پست AI کانال\s+(\+|-)\s+(@?\S+)$", text)
        if not m:
            return False
        action = m.group(1)
        channel_ref = m.group(2)
        # حذف @ اگه اولش باشه
        if channel_ref.startswith("@"):
            channel_ref = channel_ref[1:]

        self._init_extension_state()

        if action == "-":
            # حذف
            new_list = [c for c in self.ai_post_channels if c.get("username") != channel_ref]
            removed = len(self.ai_post_channels) - len(new_list)
            self.ai_post_channels = new_list
            self._save_state()
            await event.message.edit(
                f"➖ **کانال @{channel_ref} حذف شد**\n\n"
                f"📊 تعداد کانال‌ها: {len(self.ai_post_channels)}",
                parse_mode=None,
            )
        else:
            # اضافه - سعی کن entity رو resolve کنی
            try:
                entity = await self.client.get_entity(channel_ref)
                ch_data = {
                    "title": getattr(entity, "title", channel_ref),
                    "username": getattr(entity, "username", None) or channel_ref,
                    "id": entity.id,
                }
                # چک تکراری نبودن
                if any(c.get("id") == entity.id for c in self.ai_post_channels):
                    await event.message.edit(f"⚠️ کانال @{channel_ref} از قبل اضافه شده.", parse_mode=None)
                    return True
                self.ai_post_channels.append(ch_data)
                self._save_state()
                await event.message.edit(
                    f"➕ **کانال @{channel_ref} اضافه شد**\n\n"
                    f"📛 نام: {ch_data['title']}\n"
                    f"📊 تعداد کانال‌ها: {len(self.ai_post_channels)}",
                    parse_mode=None,
                )
            except Exception as exc:
                await event.message.edit(
                    f"❌ خطا در اضافه کردن کانال:\n\n`{exc}`\n\n"
                    f"💡 مطمئن شو که:\n"
                    f"• ربات در کانال عضو هست\n"
                    f"• یا یوزرنیم صحیح است",
                    parse_mode=None,
                )
        return True

    async def cmd_ai_post_list_channels(self, event, text):
        """نمایش لیست کانال‌های منبع."""
        self._init_extension_state()
        if not self.ai_post_channels:
            await event.message.edit(
                "📋 **کانال‌های منبع خالی**\n\n"
                "💡 برای اضافه کردن:\n"
                "`پست AI کانال + @channel_name`\n\n"
                "⚠️ اگه خالی باشه، AI از همه کانال‌های اکانت استفاده می‌کنه.",
                parse_mode=None,
            )
            return True
        lines = ["📋 **کانال‌های منبع:**\n"]
        for i, ch in enumerate(self.ai_post_channels, 1):
            username = ch.get("username", "")
            title = ch.get("title", "ناشناس")
            lines.append(f"{i}. {title}" + (f" (@{username})" if username else ""))
        await event.message.edit("\n".join(lines), parse_mode=None)
        return True

    async def cmd_ai_post_search(self, event, text):
        """جستجوی موضوع + جمع‌آوری از کانال‌ها (مرحلهٔ ۱ از ۳ پایپ‌لاین)."""
        m = re.match(r"^پست AI جستجو\s+(.+)$", text)
        if not m:
            return False
        query = m.group(1).strip()[:200]
        self._init_extension_state()
        config = self.ai_post_config
        config["topic"] = query
        config["search_query"] = query

        await event.message.edit(
            f"🔍 **مرحله ۱/۳: جستجو و جمع‌آوری برای «{query}»**\n\n"
            "├ جستجوی گوگل... 🔎\n"
            "└ جمع‌آوری از کانال‌ها... 📥",
            parse_mode=None,
        )

        # جستجوی گوگل
        search_results = await self._ai_post_google_search(query, num_results=5)
        # جمع‌آوری از کانال‌ها
        collected = await self._ai_post_collect_from_channels(limit_per_channel=8)

        # ذخیره برای مراحل بعدی
        config["last_search_results"] = search_results
        config["last_collected"] = collected
        self._save_state()

        msg = f"✅ **مرحله ۱ کامل شد: «{query}»**\n\n"
        msg += "📊 **آمار جمع‌آوری:**\n"
        msg += f"├ پست‌های کانال‌ها: {len(collected)} مورد\n"
        msg += f"└ نتایج گوگل: {len(search_results)} مورد\n\n"
        if collected:
            msg += "📌 **نمونه پست‌ها:**\n"
            for p in collected[:3]:
                preview = p['text'][:80].replace('\n', ' ')
                msg += f"├ {p['channel']}: {preview}...\n"
            msg += "\n"
        msg += "💡 **مرحله بعد:**\n"
        msg += "`پست AI تولید` — ادیت حرفه‌ای + انتشار"
        await event.message.edit(msg, parse_mode=None)
        return True

    async def cmd_ai_post_generate(self, event, text):
        """تولید پست حرفه‌ای با AI (مرحلهٔ ۲ و ۳: ادیت + انتشار).

        اگه جستجو قبلاً نشده، اول جستجو می‌کنه.
        """
        self._init_extension_state()
        config = self.ai_post_config
        query = config.get("search_query") or config.get("topic") or ""

        # اگه قبلاً جستجو نشده، خودش اتومات جمع می‌کنه
        if not config.get("last_collected") and not config.get("last_search_results"):
            await event.message.edit(
                "⏳ **اول جستجو اتومات می‌کنم...**\n"
                "می‌تونی موضوع رو با `پست AI جستجو [موضوع]` هم مشخص کنی.",
                parse_mode=None,
            )
            # اگه topic نداریم، از last_collected کانال‌ها استفاده کن
            collected = await self._ai_post_collect_from_channels(limit_per_channel=8)
            config["last_collected"] = collected
        else:
            collected = config.get("last_collected", [])

        # اگه search_query داریم ولی نتایج نه، بگیر
        search_results = config.get("last_search_results", [])
        if config.get("search_query") and not search_results:
            search_results = await self._ai_post_google_search(
                config["search_query"], num_results=5
            )
            config["last_search_results"] = search_results

        if not collected:
            await event.message.edit(
                "❌ **محتوایی برای ادیت پیدا نشد**\n\n"
                "💡 چک کن:\n"
                "• ربات در کانال‌ها عضو باشه\n"
                "• کانال‌ها پست داشته باشن\n"
                "• یا موضوع مشخصی بزن: `پست AI جستجو موضوع`",
                parse_mode=None,
            )
            return True

        await event.message.edit(
            f"🤖 **مرحله ۲/۳: ادیت حرفه‌ای با AI**\n\n"
            f"├ {len(collected)} پست از کانال‌ها\n"
            f"├ {len(search_results)} نتیجه از گوگل\n"
            f"└ موضوع: {config.get('topic', 'عمومی')}",
            parse_mode=None,
        )

        if not await self._ai_available():
            await event.message.edit(
                "❌ **API key تنظیم نشده**\n\n"
                "💡 با فرمان `تنظیم کلید [کلید]` کلید API رو تنظیم کن.",
                parse_mode=None,
            )
            return True

        # ادیت حرفه‌ای
        post_text, error = await self._ai_post_professional_edit(
            collected, search_results, config
        )
        if not post_text:
            await event.message.edit(
                f"❌ **خطا در ادیت حرفه‌ای:**\n\n`{error}`",
                parse_mode=None,
            )
            return True

        # ذخیره draft
        draft_id = len(self.ai_post_drafts) + 1
        self.ai_post_drafts.append({
            "id": draft_id,
            "text": post_text,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "topic": config.get("topic", ""),
            "sources": len(collected),
            "google_results": len(search_results),
        })
        self.ai_post_drafts = self.ai_post_drafts[-50:]

        await event.message.edit(
            f"✨ **پست حرفه‌ای ساخته شد #{draft_id}**\n\n"
            f"────────────────────\n"
            f"{post_text}\n"
            f"────────────────────\n\n"
            f"📊 **آمار:**\n"
            f"├ منابع: {len(collected)} پست از کانال‌ها\n"
            f"├ جستجو: {len(search_results)} نتیجه از گوگل\n"
            f"└ طول: {len(post_text)} کاراکتر\n\n"
            f"💡 **برای انتشار:**\n`پست AI انتشار`",
            parse_mode=None,
        )
        return True

    async def cmd_ai_post_publish(self, event, text):
        """انتشار آخرین draft تولید‌شده."""
        self._init_extension_state()
        if not self.ai_post_drafts:
            await event.message.edit(
                "❌ **پیش‌نویسی نیست**\n\n"
                "💡 اول `پست AI تولید` رو بفرست.",
                parse_mode=None,
            )
            return True
        last_draft = self.ai_post_drafts[-1]
        # انتشار به مقصد تنظیم‌شده (یا همین چت)
        config = self.ai_post_config
        target = config.get("target_chat_id") or event.chat_id
        target_title = config.get("target_chat_title") or "همین چت"
        try:
            # استفاده از safe_send
            sent_msg = await _safe_send_message(
                self.client, target, last_draft["text"], parse_mode=None
            )
            if sent_msg is None:
                await event.message.edit("❌ ارسال ناموفق بعد از چند تلاش.", parse_mode=None)
                return True
            # ثبت در تاریخچه
            self.ai_post_history.append({
                "draft_id": last_draft["id"],
                "published_at": datetime.now().isoformat(timespec="seconds"),
                "chat_id": str(target),
            })
            self.ai_post_history = self.ai_post_history[-200:]
            self.ai_post_stats_log.append({
                "type": "publish",
                "at": datetime.now().isoformat(timespec="seconds"),
            })
            self.ai_post_config["last_published"] = time.time()
            self._save_state()
            # نمایش فارسی شماره
            id_display = _to_persian_digits(str(last_draft['id']))
            await event.message.edit(
                f"✅ **پست منتشر شد!**\n\n"
                f"📝 شماره: #{id_display}\n"
                f"📍 مقصد: {target_title}\n"
                f"⏰ زمان: {datetime.now().strftime('%H:%M:%S')}",
                parse_mode=None,
            )
        except Exception as exc:
            logger.exception(f"AI Post: خطا در انتشار: {exc}")
            await event.message.edit(f"❌ خطا در انتشار: `{exc}`", parse_mode=None)
        return True

    async def cmd_ai_post_schedule(self, event, text):
        """تنظیم زمان‌بندی خودکار برای انتشار پست."""
        m = re.match(r"^پست AI زمان\s+([\d۰-۹]+)\s+(ساعت|دقیقه)$", text)
        if not m:
            return False
        value = int(m.group(1))
        unit = m.group(2)
        if unit == "ساعت":
            hours = value
            if hours < 1 or hours > 168:
                await event.message.edit("❌ بازه مجاز: ۱ تا ۱۶۸ ساعت (۱ هفته).", parse_mode=None)
                return True
        else:
            hours = value / 60.0
            if hours < 0.5 or hours > 168:
                await event.message.edit("❌ بازه مجاز: ۳۰ دقیقه تا ۱۶۸ ساعت.", parse_mode=None)
                return True
        self._init_extension_state()
        self.ai_post_config["schedule_hours"] = hours
        self.ai_post_config["enabled"] = True
        self._save_state()
        await event.message.edit(
            f"⏰ **زمان‌بندی تنظیم شد**\n\n"
            f"📊 هر **{hours} ساعت** یه پست خودکار تولید و منتشر میشه.\n\n"
            f"💡 برای توقف: `پست AI خاموش`",
            parse_mode=None,
        )
        return True

