    async def cmd_ai_post_toggle(self, event, text):
        """روشن/خاموش کردن AI پست."""
        m = re.match(r"^پست AI\s+(روشن|خاموش)$", text)
        if not m:
            return False
        mode = m.group(1)
        self._init_extension_state()
        self.ai_post_config["enabled"] = (mode == "روشن")
        self._save_state()
        status = "فعال" if mode == "روشن" else "غیرفعال"
        emoji = "🟢" if mode == "روشن" else "🔴"
        await event.message.edit(
            f"{emoji} **پست AI {status} شد**\n\n"
            f"{'✅ پست‌های خودکار فعال هستن.' if mode == 'روشن' else '⏸️ پست‌های خودکار متوقف شدن.'}",
            parse_mode=None,
        )
        return True

    async def cmd_ai_post_stats(self, event, text):
        """نمایش آمار کامل AI پست."""
        self._init_extension_state()
        # آمار از log
        publishes = [s for s in self.ai_post_stats_log if s.get("type") == "publish"]
        today = datetime.now().strftime("%Y-%m-%d")
        today_pubs = sum(1 for s in publishes if s.get("at", "").startswith(today))
        # ۷ روز اخیر
        from collections import Counter
        days_counter = Counter()
        for s in publishes:
            day = s.get("at", "")[:10]
            if day:
                days_counter[day] += 1
        last_7 = sum(1 for s in publishes if (datetime.now() - _parse_iso(s.get("at", ""))).days < 7 if s.get("at"))
        msg = f"📊 **آمار کامل پست AI**\n\n"
        msg += f"📈 **کل:** {len(publishes)} پست\n"
        msg += f"📅 **امروز:** {today_pubs} پست\n"
        msg += f"📆 **۷ روز اخیر:** {last_7} پست\n\n"
        msg += f"📋 **موجودی:**\n"
        msg += f"├ پیش‌نویس‌ها: {len(self.ai_post_drafts)}\n"
        msg += f"├ کانال‌های منبع: {len(self.ai_post_channels)}\n"
        msg += f"└ تاریخچه: {len(self.ai_post_history)} مورد\n\n"
        if days_counter:
            msg += "📊 **پست‌های ۷ روز اخیر (بر اساس روز):**\n"
            for day, count in sorted(days_counter.items(), reverse=True)[:7]:
                msg += f"├ {day}: {count} پست\n"
        await event.message.edit(msg, parse_mode=None)
        return True

    async def cmd_ai_post_auto(self, event, text):
        """ساخت اتوماتیک پست حرفه‌ای (pipeline کامل).

        کاربر فقط می‌گه `پست AI بساز` و ربات:
        ۱. از همه کانال‌های اکانت پست جمع می‌کنه
        ۲. موضوع رو از آخرین پست یا topic ذخیره‌شده می‌گیره
        ۳. گوگل می‌زنه
        ۴. حرفه‌ای ادیت می‌کنه
        ۵. منتشر می‌کنه
        """
        self._init_extension_state()
        config = self.ai_post_config
        # موضوع رو از config بگیر، یا "اخبار روز"
        topic = config.get("topic") or "اخبار و موضوعات داغ روز"
