async def show_extension_menu(bot, event):
    """نمایش منوی اصلی مرکز اکستنشن‌ها."""
    from collections import Counter
    cat_counts = Counter()
    for f in EXTENSION_FEATURES:
        if "ai_post" not in f[0]:
            cat_counts[f[1]] += 1
    ai_count = sum(1 for f in EXTENSION_FEATURES if "ai_post" in f[0])
    base_count = 900  # قابلیت‌های اصلی shadowself.py
    total = base_count + EXTENSION_FEATURE_COUNT
    text = EXTENSION_MENU_BODY.format(
        total=EXTENSION_FEATURE_COUNT,
        ext_count=EXTENSION_FEATURE_COUNT,
        total_count=total,
    )
    try:
        await event.edit(text, parse_mode=None, buttons=EXTENSION_MENU_BUTTONS)
    except Exception:
        await event.respond(text, parse_mode=None, buttons=EXTENSION_MENU_BUTTONS)


async def show_extension_category(bot, event, category):
    """نمایش یک دسته از اکستنشن‌ها."""
    if category not in EXTENSION_CATEGORY_BODIES:
        await event.answer("دسته نامعتبر", alert=True)
        return
    text = EXTENSION_CATEGORY_BODIES[category]
    buttons = [
        [Button.inline("🔙 منوی اصلی اکستنشن‌ها", b"shadow:ext_menu")],
        [Button.inline("🏠 shadow:menu:third", b"shadow:menu:shadow:menu:third")],
    ]
    try:
        await event.edit(text, parse_mode=None, buttons=buttons)
    except Exception:
        await event.respond(text, parse_mode=None, buttons=buttons)


async def show_extension_full_list(bot, event):
    """نمایش لیست کامل ۱۱۷ قابلیت."""
    from collections import defaultdict
    by_cat = defaultdict(list)
    for f in EXTENSION_FEATURES:
        cat = f[1] if "ai_post" not in f[0] else "🤖 AI پست"
        by_cat[cat].append(f[2])
    text = "📋 **لیست کامل ۱۱۷ قابلیت**\n\n"
    for cat, items in sorted(by_cat.items()):
        text += f"**{cat}** ({len(items)} مورد):\n"
        for i, item in enumerate(items[:25], 1):
            text += f"  {i}. {item}\n"
        if len(items) > 25:
            text += f"  ... و {len(items) - 25} مورد دیگر\n"
        text += "\n"
    text += f"🔢 **جمع:** {EXTENSION_FEATURE_COUNT} قابلیت فعال\n"
    buttons = [
        [Button.inline("🔙 منوی اصلی اکستنشن‌ها", b"shadow:ext_menu")],
        [Button.inline("🏠 shadow:menu:third", b"shadow:menu:third")],
    ]
    try:
        # اگه پیام خیلی بلند شد، فقط ۳۰ خط اول
        if len(text) > 4000:
            text = text[:4000] + "\n\n... (ادامه دارد)"
        await event.edit(text, parse_mode=None, buttons=buttons)
    except Exception:
        await event.respond(text, parse_mode=None, buttons=buttons)


# ====== Hook برای اتصال به dispatch اصلی ======

def _ext_menu_callback(bot, event, data):
    """پردازش callback های مربوط به منوی اکستنشن‌ها.

    مقادیر data ممکن:
    - shadow:ext_menu → منوی اصلی
    - shadow:ext_cat:XXX → یک دسته
    - shadow:ext_full_list → لیست کامل
    """
    if data == b"shadow:ext_menu":
        return show_extension_menu(bot, event)
    if data.startswith(b"shadow:ext_cat:"):
        cat = data.decode("utf-8").split(":", 2)[2]
        return show_extension_category(bot, event, cat)
    if data == b"shadow:ext_full_list":
        return show_extension_full_list(bot, event)
    return None  # نامعتبر


