    """پردازش فرمان‌های متنی مربوط به اکستنشن‌ها.

    مثل: 'مرکز اکستنشن‌ها'، 'اکستنشن‌ها'، 'extension'
    """
    text = (text or "").strip()
    # نرمال‌سازی
    normalized = _from_persian_digits(text).lower().strip()
    triggers = [
        "مرکز اکستنشن‌ها", "مرکز اکستنشن ها",
        "اکستنشن‌ها", "اکستنشن ها", "اکستنشن",
        "extension", "extensions",
        "قابلیت‌های جدید", "قابلیت های جدید",
        "قابلیت‌های extension", "100 قابلیت", "۱۰۰ قابلیت",
    ]
    if normalized in triggers or any(t in normalized for t in triggers):
        await show_extension_menu(bot, event)
        return True
    return False


