class ExtensionDispatcher:
    """dispatcher مرکزی برای extension features. به ShadowSalfBot وصل میشه."""

    @classmethod
    def attach(cls, bot_class):
        """وصل کردن extension به کلاس ShadowSalfBot."""
        # اضافه کردن متدهای cmd_* (عمومی)
        for attr_name in dir(ExtensionsMixin):
            if attr_name.startswith("cmd_"):
                method = getattr(ExtensionsMixin, attr_name)
                setattr(bot_class, attr_name, method)

        # اضافه کردن متدهای private (کمکی) - اینا _ai_post_* هستن
        for attr_name in dir(ExtensionsMixin):
            if attr_name.startswith("_ai_post_") or attr_name.startswith("_init_extension_state"):
                method = getattr(ExtensionsMixin, attr_name)
                setattr(bot_class, attr_name, method)

        # اضافه کردن متد handle_extensions به کلاس
        setattr(bot_class, "handle_extensions", cls._make_handle_extensions())
        setattr(bot_class, "handle_extension_command", cls._make_handle_command())
        # اضافه کردن متدهای کمکی global
        def _recover_for_self(self_obj):
            return _recover_batch_state(self_obj)
        setattr(bot_class, "_recover_batch_state", _recover_for_self)
        # بازیابی state موقع attach (جلوگیری از deadlock)
        try:
            # فقط اگه متد _init_extension_state وجود داشته باشه wrap کن
            if hasattr(bot_class, "_init_extension_state"):
                original_init_state = bot_class._init_extension_state
                def wrapped_init(self_obj):
                    original_init_state(self_obj)
                    # بعد از init، recovery state
                    try:
                        _recover_batch_state(self_obj)
                    except Exception:
                        pass
                setattr(bot_class, "_init_extension_state", wrapped_init)
        except Exception as exc:
            logger.warning(f"خطا در wrap کردن init: {exc}")
        return True

    @classmethod
    def _make_handle_extensions(cls):
        """ساخت متد handle_extensions برای ShadowSalfBot."""
        async def handle_extensions(self, event, text):
            """پردازش فرمان‌های extension."""
            self._init_extension_state()
            return await self.handle_extension_command(event, text)
        return handle_extensions

    @classmethod
    def _make_handle_command(cls):
        """ساخت متد handle_extension_command."""
        async def handle_extension_command(self, event, text):
            """پردازش یک فرمان extension.

            ابتدا متن رو نرمال‌سازی می‌کنه (ارقام فارسی → انگلیسی)، سپس:
            ۱. literal match (exact)
            ۲. prefix match (شروع با)
            ۳. pattern match (regex)
            """
            text = text.strip()
            # نرمال‌سازی ارقام فارسی به انگلیسی برای پردازش بهتر
            normalized_text = _from_persian_digits(text)

            # ابتدا فرمان‌های literal (با متن اصلی)
            if text in EXTENSION_COMMANDS:
                method_name = EXTENSION_COMMANDS[text]
                method = getattr(self, method_name, None)
                if method:
                    return await method(event, text)

            # سپس prefix match - اگه کاربر فقط اول فرمان رو نوشته
            # مثلاً "پست AI ب" → "پست AI بساز"
            if len(normalized_text) >= 4:
                for cmd_text, method_name in EXTENSION_COMMANDS.items():
                    # اگه فرمان با متن شروع می‌شه و حداقل ۴ حرف مشترک هست
                    if (
                        normalized_text.startswith(_from_persian_digits(cmd_text[:6]))
                        and len(normalized_text) >= len(cmd_text) - 3
                    ):
                        # بررسی کن که کلمهٔ بعدی هم خالی یا عدد باشه
                        remainder = normalized_text[len(_from_persian_digits(cmd_text)):].strip()
                        if not remainder or remainder[0].isdigit() or remainder[0] == " ":
                            method = getattr(self, method_name, None)
                            if method:
                                return await method(event, text)

            # سپس فرمان‌های الگو-مبنا
            for feature_key, _, _, command_text, pattern in EXTENSION_FEATURES:
                # اول با متن اصلی
                m = re.match(pattern, text)
                if not m:
                    # بعد با متن normalized
                    m = re.match(pattern, normalized_text)
                if m:
                    # پیدا کردن متد بر اساس command_text
                    method_name = EXTENSION_COMMANDS.get(command_text)
                    if not method_name:
                        # استخراج از feature_key: tools.bmi_calc → bmi_calc
                        parts = feature_key.split(".", 1)
                        if len(parts) > 1:
                            short_key = parts[1]
                        else:
                            short_key = parts[0]
                        method_name = "cmd_" + short_key
                    method = getattr(self, method_name, None)
                    if method:
                        return await method(event, text)
            return False
        return handle_extension_command


