# ============================================================================
# Auto-install: وقتی فایل import میشه، خودش به ShadowSalfBot وصل میشه
# ============================================================================

def _auto_install():
    """اتصال خودکار — وقتی این فایل ایمپورت بشه، خودش mixin رو وصل می‌کنه."""
    try:
        # پیدا کردن ShadowSalfBot در هر جایی از ماژول‌های لودشده
        import sys
        for module_name, module in list(sys.modules.items()):
            if module is None:
                continue
            cls = getattr(module, "ShadowSalfBot", None)
            if cls is not None:
                ExtensionDispatcher.attach(cls)
                return True
        return False
    except Exception as exc:
        # خطا نده، فقط print کن
        print(f"[extensions] auto-install failed: {exc}")
        return False


# helper: digits regex - فارسی و انگلیسی
_DIGIT = r"[\d۰-۹]"


# وقتی import میشه، خودش نصب میشه
_installed = _auto_install()
()
